/* Helpful tab guides. Researched from cited sources (see each guide's src list). Generated from research/guides/*.json; map placement from research/mapplace.py. */
window.GT_GUIDES=[{"id":"ce","n":"Crota's End","type":"Raid","players":"6","loc":"The Hellmouth (the Moon)","rel":"Season of the Witch (September 2023); originally The Dark Below (2014)","intro":"A Hive raid deep under the Moon, brought back from Destiny 1. Everything revolves around the Chalice of Light: pass it around to charge it, and the player you take it from becomes Enlightened, which lets them light lanterns, build bridges, use Hive swords and hit the Oversoul.","basics":["Chalice of Light: hold it until its bar fills (four quarters). Holding it past full kills you: someone must take it from you within 10 seconds or you die to Engulfed in Light.","Enlightened: given to you when someone takes your fully charged Chalice. It lights lanterns, starts or speeds up bridges, lets you pick up swords, pass barriers, Expunge enemies and destroy the Oversoul. Using it gives Drained of Light (45 seconds), which stops you picking up the Chalice.","Preservation node: a small node to place the Chalice in and take it back from."],"enc":[{"n":"The Hellmouth (opening)","kind":"trav","goal":"Build the first bridge.","steps":["Pick up the Chalice, charge it, and use it on the plate to add the charge.","Another player takes the Chalice and repeats until the bridge is built."]},{"n":"The Abyss","kind":"enc","goal":"Light lantern groups through the dark path before Engulfed in Darkness runs out, then build the bridge at the end.","steps":["Pass the Chalice around until players are Enlightened.","Weight of Darkness builds to 10 stacks and slows you (no sprinting or double jumps). It isn't lethal; standing by a lit lantern reduces it.","Engulfed in Darkness is a 60-second countdown that kills you at zero. Lighting a lantern or preserving the Chalice resets it for everyone.","Some lanterns have a preservation node beside them (the first always does). Preserve the Chalice there to activate the next group of lanterns, then take it back.","Use Enlightened to light a lantern; it explodes after about 15 seconds. Keep going group by group to the end.","At the end, use Enlightened on the plate to start building the bridge, and survive the waves of Unstoppable Ogres, Hive Knights and Thrall. Cross when the game says the path is clear."],"chal":{"n":"Conservation of Energy","d":"Preserve the Chalice of Light before enlightening lamps."}},{"n":"The Bridge","kind":"enc","goal":"Get all six players across the bridge using the Chalice and Hive swords, then kill the Gatekeepers on the far side.","steps":["The bridge can only be crossed while holding the Chalice or a Hive sword. Gatekeepers can only be damaged with a Hive sword.","Get someone Enlightened and use the Chalice on the plate to start building the bridge.","While someone is on the center plate, the Annihilator Totems are active: one player must stand under each, or the team wipes.","A Swordbearer appears when construction starts and after each Gatekeeper dies. An Enlightened player picks up its sword (it vanishes if left on the ground) and crosses when the bridge is built.","The sword carrier kills the Gatekeeper on the far side, then preserves the sword at a node. Repeat until three players are across.","The far-side three take over: one on their plate, one under each totem on their side. Send the rest across with swords; with two left, one takes a sword and the other carries the Chalice across.","With all six across, survive the waves until Gatekeepers spawn. Pass the Chalice to get players Enlightened, preserve it at the node near the center door, and use the preserved swords on the Gatekeepers."],"wipes":["No player under an active Annihilator Totem."],"chal":{"n":"Precarious Balance","d":"Players may only cross the bridge when there is no one standing on the plate to form it."}},{"n":"The Thrallway","kind":"trav","goal":"Climb the hill through the barriers.","steps":["Kill Thrall and destroy Shriekers as you climb.","Holding the Chalice makes you Enlightened, which passes a barrier; killing a Shrieker removes a barrier.","At the top, deposit the Chalice to open the hole in the ground."]},{"n":"Ir Yût, the Deathsinger","kind":"enc","goal":"Kill the Wizards in the towers and rooms at the same time to break Ir Yût's shield, then damage her to each notch before Dark Liturgy ends.","steps":["Split into two groups of three, left and right. Kill the Blistered Knights quickly; killing the Shriekers opens the center crystal room with the Chalice.","Charge the Chalice so three players are Enlightened (Enlightened lets you pass the green barriers; you can't pick up the Chalice while you have it).","A scout calls out where the Wizards are: the top and bottom tower floors and the three rooms above the center crystal, one Wizard per room.","Kill the Wizards together. Each one removes a layer of her shield.","With all Wizards down, damage Ir Yût. Enlightened players can Expunge her for a big hit, which uses up their buff.","Each damage phase adds one Wizard: three, then four, then five."],"wipes":["Dark Liturgy starts when a Wizard in the tower dies or after 3 minutes, and wipes the team at zero unless Ir Yût has been damaged to the notch in her health bar."],"chal":{"n":"Equal Vessels","d":"Each player must rotate the Chalice of Light buff in the same order, every round and throughout the encounter."}},{"n":"Crota, Son of Oryx","kind":"enc","goal":"Break Crota's shield with Hive swords, damage him, and destroy the Oversoul at the end of each phase.","steps":["Presence of Crota stops Chalice swaps except while standing in a beam of Light.","Kill the Hive Knight Boomers in the towers to summon Ogres and a Swordbearer at the middle door. Its sword disappears after a few seconds.","An Enlightened player picks up the sword and hits Crota to remove his shield; it takes two or three swords. Either use one sword at a time (more players stay on adds) or wait until three players have swords and hit him together.","Each damage phase summons an Oversoul that wipes the team after 30 seconds unless an Enlightened player destroys it; destroying it ends the damage phase. Destroy it at the last moment.","Aim for at least four Enlightened players: three for swords and one for the Oversoul. Extras can Expunge Crota for burst damage."],"dps":"Plan for at least three damage phases before the final stand. Keep a Well of Radiance up at all times (Crota destroys Wells easily on higher difficulties; use more than one, or a Ward of Dawn to protect it). Push him to the final stand with Special weapons, keeping Heavy and Supers. There is no Oversoul before the final stand, but the final stand has one, so keep one Enlightened player. At his last chunk of health he turns immune for a few seconds: grab Heavy and avoid his slam.","chal":{"n":"All for One","d":"Break Crota's shield in one attempt."}}],"chests":["The Abyss: after building the bridge and dropping into the Hellmouth, stay near the arena wall and check the doors with faint yellow lights. The chest is behind one of them. It stays put if you wipe but can move if you leave and come back.","Thrallway: go through it immediately after the Bridge. Pass the Chalice so each player is Enlightened, clear the green barriers and kill the Shriekers. When the last doorway is cleared, the final Chalice holder must deposit it before the back door closes; a fast deposit reopens that door and shows the chest."],"loot":{"The Abyss":["Abyss Defiant","Fang of Ir Yût","Song of Ir Yût","Helmet","Gauntlets","Chest armor"],"The Bridge":["Fang of Ir Yût","Oversoul Edict","Swordbreaker","Gauntlets","Chest armor","Leg armor"],"Ir Yût":["Word of Crota","Oversoul Edict","Song of Ir Yût","Chest armor","Leg armor","Class item"],"Crota":["Word of Crota","Abyss Defiant","Swordbreaker","Helmet","Leg armor","Class item","Necrochasm (exotic)"]},"lootNote":"Necrochasm is tied to the final encounter; its exact source is shown under the loot (from Bungie's own data).","src":[["Shacknews: Crota's End raid guide","https://shacknews.com/article/136793/crotas-end-raid-guide-destiny-2"],["Shacknews: Crota's End loot table","https://shacknews.com/article/136980/crotas-end-loot-table-destiny-2"],["GINX: Crota's End secret chests","https://www.ginx.tv/en/secret-chests-crotas-end"],["Kyber's Corner: raid challenges","https://kyberscorner.com/destiny2/raid-challenges/"]],"b":"Crota’s End","k":["Crota's End"],"pl":{"0_1":"top","1_0":1,"2_0":2,"3_0":4,"4_0":5}},{"id":"dsc","n":"Deep Stone Crypt","type":"Raid","players":"6","loc":"Europa","rel":"Beyond Light (November 2020)","intro":"A Fallen raid under Europa and aboard the Morning Star. Its core is three augments you take from enemies and pass around: Operator (red), Scanner (yellow) and Suppressor (blue). Encounters: the Desolation blizzard, Crypt Security, Atraks-1, the space walk, the Descent and Taniks, the Abomination.","basics":["Operator (red, from an Operator Vandal): shoots panels and frees trapped players.","Scanner (yellow, from a Hacker Vandal): sees what the team can't (the right panels, duplicates and deposit boxes) and calls it out.","Suppressor (blue, from a Suppressor Vandal): used in the Taniks fights to stun him.","A player can hold one augment at a time, and so can a terminal. Use terminals to pass augments between players and floors."],"enc":[{"n":"Desolation (the blizzard)","kind":"trav","goal":"Cross the frozen surface from shelter to shelter without freezing.","steps":["Being outside the warm shelter bubbles builds Frostbite. Ten stacks kill you.","Lamps and Web Mines mark the route. Clear all enemies at a shelter to make it a checkpoint.","Six shelters stand between you and the Crypt. Sparrows are allowed and make it quicker."]},{"n":"Crypt Security","kind":"enc","goal":"Shoot the right panels in the basement, then destroy the fuses upstairs. Six fuses in total.","steps":["Kill an Operator Vandal for the Operator augment and a Hacker Vandal for the Scanner augment.","The Operator goes to the basement. The Scanner, upstairs, sees which panels are correct through the glass columns and calls them.","The Operator shoots four basement panels (two on the dark side, two on the light side) within about a minute before the basement kills them. This starts the damage phase.","Then swap augments through the terminals (Operator up, Scanner down): the player in the basement now has the Scanner, sees which fuses are lit, and calls them for the upstairs team to destroy.","A Sentinel Servitor disables the augment terminals; kill it.","If the Operator dies, wait for another Operator Vandal to reclaim the augment."],"wipes":["Shooting a fuse that isn't one of the called (lit) ones wipes the team."],"chal":{"n":"Red Rover","d":"All Guardians must be operator during the encounter and shoot the two panels on the lower level."}},{"n":"Atraks-1, Fallen Exo","kind":"enc","goal":"Kill the correct Atraks-1 duplicate each round across the station and the laboratory, and get rid of every Replication orb.","steps":["Grab the purple orb to start. The team splits between the lower laboratory and the orbital station; the Operator shoots panels to send elevator pods up and to open airlock doors.","The Scanner identifies the correct duplicate (it glows yellow) and calls it. Killing the wrong one or taking too long causes Replicated Ruin, a wipe.","Killing the correct duplicate drops an orb. Whoever picks it up gets Atraks-1 Replication and has 45 seconds to throw it out of an airlock in the station. The Operator can shoot the debuff to add time.","Destroy the six Sentinel Servitors to start the damage phase. Atraks-1's Extinction Protocol moves between the station and the laboratory across four damage phases.","At 25% health, the whole team goes up to the station."],"dps":"Final stand: eight duplicates spawn in the station. Fast teams can win without dealing with the orbs.","wipes":["Replicated Ruin: the correct duplicate wasn't killed in time.","A Replication orb that isn't disposed of kills its holder.","Standing in an airlock too long ejects you into space."],"chal":{"n":"Copies of Copies","d":"Do not send any \"Atraks-1 Replication\" debuffs into airlocks/space."}},{"n":"The space walk","kind":"trav","goal":"Jump along the outside of the Morning Star to reach the next area.","steps":["A jumping section across the station's exterior, with Shanks throughout.","It ends with Brigs and Dark Council Guards outside the entrance."]},{"n":"The Descent (Taniks, Reborn)","kind":"enc","goal":"Deposit six nuclear cores (three rounds of two) to stop the station crashing into Europa, then escape.","steps":["Split into three pairs. Kill an Operator Vandal, a Hacker Vandal and a Suppressor Vandal for the three augments.","When the alarm sounds, the Operator shoots a red panel so that two cores spawn instead of three.","The Scanner marks the two correct deposit boxes in yellow.","The Suppressor stuns Taniks by being shot by him while standing under each of the three Security Drones; this unlocks the boxes.","Cores build Radiation on whoever carries them, which stops sprinting and double jumps and kills at ten stacks. Each box takes one core.","After two cores, augments switch off. Put them in a terminal and pass them on so each pair rotates.","After the sixth core, drop into the opening hatch and run for the escape pod. Taniks chases you and kills anyone who is too slow."],"wipes":["Cores that aren't deposited in time explode and wipe the fireteam.","Ten Radiation stacks kill the carrier."],"chal":{"n":"Of All Trades","d":"All Guardians members must perform each role at least once (Operator, Scanner, and Suppressor)."}},{"n":"Taniks, the Abomination","kind":"enc","goal":"Stop Taniks's meteor attack with nuclear cores from his jets, then damage him from between his shields.","steps":["Split into three teams. Get the Scanner (Hacker Vandal in the blue area), Operator (Operator Vandal near spawn) and Suppressor (Suppressor Vandal near the orange site).","Shoot Taniks's booster jets during his attack; destroyed jets drop nuclear cores.","The Scanner marks the correct two of the six deposit bins. Depositing in the wrong bin kills you instantly.","The Operator shoots the spheres that trap players.","The Suppressor passes through three of the nine drones in an area to stun Taniks. Suppressing too fast can switch augments off.","Players without an augment carry the cores. Turbulent Barrage meteors need two to four cores to stop; too few causes Turbulent Detonation, an instant wipe."],"dps":"After four cores, Taniks creates a Shock Field. Stand between his two shields: too close does Arc damage, too far gets you killed by debris. You get three damage phases before he enrages. Final stand: he teleports around the arena; kill him within five teleports or the team wipes.","chal":{"n":"The Core Four","d":"Guardians must dunk all four cores before each DPS phase."}}],"chests":["During the blizzard, before entering the first encounter's door: look for a series of ledges to climb up behind you, to the left. Keep climbing; the chest is in a small alcove. Watch your Frostbite stacks.","After Atraks-1, on the way to the Descent: where large blades split the path, the right path continues the raid and the left leads to the chest. Climb the platforms to the one with red lights."],"loot":{"Crypt Security":["Trustee","Gauntlets","Leg armor","Class item"],"Atraks-1":["Heritage","Succession","Gauntlets","Leg armor","Class item"],"The Descent":["Heritage","Posterity","Gauntlets","Chest armor","Class item"],"Taniks, the Abomination":["Commemoration","Bequest","Helmet","Chest armor","Leg armor","Eyes of Tomorrow (exotic)"]},"lootNote":"Eyes of Tomorrow drops only from Taniks, the Abomination.","src":[["Destinypedia: Deep Stone Crypt (raid)","https://destinypedia.com/Deep_Stone_Crypt_(Raid)"],["Gfinity: Deep Stone Crypt guide","https://www.gfinityesports.com/destiny/destiny-2-deep-stone-crypt-guide-beyond-light-raid-ps5-xbox-pc/"],["Charlie Intel: DSC secret chests","https://www.charlieintel.com/destiny/how-to-find-the-deep-stone-crypt-secret-chests-in-destiny-2-beyond-light-66367/"],["Shacknews: DSC loot table","https://shacknews.com/article/137524/deep-stone-crypt-loot-table-destiny-2"],["Kyber's Corner: raid challenges","https://kyberscorner.com/destiny2/raid-challenges/"]],"b":"Deep Stone Crypt","k":["Deep Stone Crypt"],"pl":{"1_0":1,"1_1":1,"2_0":2,"2_1":2,"3_0":0,"4_0":4,"5_0":5}},{"id":"dp","n":"The Desert Perpetual","type":"Raid","players":"6","loc":"Unknown Periphery (Kepler's singularity)","rel":"The Edge of Fate (July 2025); Epic version with Ash & Iron (September 2025)","intro":"A Vex raid about time, and only the second non-linear raid: after clearing the Nursery and climbing the purple spire, you pick which of three bosses to fight first. Koregos, the Worldline unlocks after the other three (after your first clear you can go straight to it). Temporality debuffs from plates and Chronons from Minotaurs run through every fight.","basics":["Choosing a boss: at the top of the lift, three options each lead to one boss: \"All are entangled\" (Epoptes), \"Interference patterns swell\" (Agraios) and \"Axion is axiom\" (Iatros). Floating balls then point the way. You don't have to clear the opening area's enemies.","Temporality: plates give Constant, Cyclical or Absolute Temporality, usually only when every plate is occupied at once.","Chronons: dropped by Time's Burden Minotaurs and carried to rings or an hourglass.","Feats: optional modifiers (Phase Race, Token Limit, Battalions, Cutthroat Combat and per-boss challenges) that raise the loot tier."],"enc":[{"n":"Epoptes, Lord of Quanta","kind":"enc","goal":"Destroy the eyes the team calls out from inside the Hydras' shield light, then break the central eye and damage Epoptes.","roles":["Two inside readers (one per side room).","Two outside readers in the middle room.","Two on add clear, helping the inside readers."],"steps":["Clear the room and kill the two Time's Magistrate Cyclops, one on each side.","Two players step on the side plates at the same time for 30-second Temporality debuffs. The debuff lets you destroy the eyes while standing in your Lens Hydra's shield light.","Teammates call out which eyes to shoot. Destroying a wrong eye regenerates the eyes and stalls the encounter. Destroying more than three wrong triggers Broken by Quanta, a wipe.","When the debuff is spent, take it again from the plate to continue.","After all six shield eyes fall, the central (flashlight) eye can be shot, which starts the damage phase."],"dps":"During damage, random players must break the shield eyes and the flashlight eye again. Breaking the shields in time extends the phase and removes the shield blocking the boss. Expect two or three of these cycles before Epoptes resets."},{"n":"Agraios, Inherent","kind":"enc","goal":"Charge the five rings with Chronons, build Alignment Charge, and reflect Agraios's elimination attack back at it with the Detainment bubble.","roles":["Team 1 (three): one on each Temporality plate (Cyclical left, Absolute middle, Constant right).","Team 2 (three): add clear and Chronon delivery."],"steps":["Number the five rings clockwise. Time's Burden Minotaurs drop Cobalt Chronons; run them through the rings. Chronons nobody touches despawn.","Once the rings are charged, Wyverns spawn and the plates activate, giving Absolute, Constant or Cyclical Temporality.","An Agraios proxy marks visible players with Variable Elimination, which kills unless the target breaks line of sight. Taking cover resets it to 10 seconds.","The plate player whose Temporality matches the proxy's title (\"Made Constant\", \"Made Absolute\" or \"Made Cyclical\") builds Alignment Charge by running through the rings. A full charge turns their grenade into a Detainment bubble.","Use the bubble on the targeted player just before their timer ends; it ricochets the attack back at Agraios."],"dps":"Agraios moves to the center for damage. Repeat the reflect while others keep damaging; the fight continues until three deflections are done."},{"n":"Iatros, Inward-Turned","kind":"enc","goal":"Keep the hourglass filled with Chronons while a climber activates three cubes on the pillar, then damage Iatros.","roles":["Two players hunt Minotaurs and deliver Chronons.","Three players shoot the Vex boxes at the bottom of the pillars to build platforms.","One climber."],"steps":["Six Time's Burden Minotaurs drop colored Chronons (red Cinnabar or white Antimony). Deposit them in the central hourglass; this keeps the wipe timer away and advances the fight.","Shoot the Oracle diamond to start the prep phase.","The climber takes the Temporality debuff from the plate with the white energy. In time with their Diastole buff, the builders shoot the Vex box to make platforms; the climber goes up and activates a cube. Repeat for all three cubes.","Keep killing Minotaurs and depositing Chronons the whole time."],"dps":"Damage starts after the third cube and lasts roughly 15–20 seconds. Iatros uses a Void Warp Lance and a Kinetic Ground Slam, then turns immune and the cycle repeats.","wipes":["If the hourglass empties, Neomutation starts a 12-second wipe."]},{"n":"Koregos, the Worldline","kind":"enc","goal":"Before the six-minute Digitization timer ends, destroy Koregos's arms, find the true mines and fill the hourglass with Chronons. Then solve the cube puzzle on the boss and damage its head.","steps":["Interact with the central Vex cube to start; the six-minute Digitization wipe timer begins. Kill the large Hydras on the middle plates and hide behind pillars from the boss's laser.","Players stand on the three plates at once for their Temporality debuffs. Stunners with Constant Temporality destroy the boss's four arms to stop its Arc beam.","The plate players work together to identify the true mines (via Temporal Oculus), break them, and carry the Chronons to the hourglass.","When the hourglass is full, break the Vex diamond beneath it. This stops the Digitization timer.","Koregos becomes a giant platform. Climb it and solve the cube-matching puzzle around its arms four times to expose its head."],"dps":"Damage the head while dodging two Arc beams. Depositing the right Chronons in the local hourglass extends the phase. In the final stand the head spins erratically; when Decoherence Imminent! appears, get off the boss before it explodes.","wipes":["Digitization reaching zero.","Still standing on Koregos when Decoherence Imminent! ends."]}],"extra":{"t":"Epic version","b":["The Epic Desert Perpetual (from Ash & Iron) adds mechanics, changes the hub, and replaces the last boss with Koregos, Fractured in Time.","Epic-only rewards include Cusp Sempiternal, Starscape Null, The Ever-Present and the Wayward Psyche Suit."]},"loot":{"Epoptes":["Lance Ephemeral","The When and Where","Opaque Hourglass","Gauntlets","Leg armor","Class item"],"Agraios":["Intercalary","Antedate","Lance Ephemeral","Helmet","Gauntlets","Chest armor"],"Iatros":["Intercalary","Finite Maybe","The When and Where","Helmet","Chest armor","Class item"],"Koregos":["Antedate","Finite Maybe","Opaque Hourglass","Helmet","Gauntlets","Leg armor","Whirling Ovation (exotic)"]},"lootNote":"Whirling Ovation is a random drop from Koregos (once per week); completing raid triumphs raises the chance.","src":[["Destinypedia: The Desert Perpetual","https://www.destinypedia.com/The_Desert_Perpetual"],["The Game Post: Desert Perpetual raid guide","https://thegamepost.com/destiny-2-desert-perpetual-raid-guide/"],["Kyber's Corner: The Desert Perpetual","https://kyberscorner.com/destiny-2-the-desert-perpetual-raid/"]],"b":"Desert Perpetual","k":["Desert Perpetual"],"pl":{"0_2":"top","1_0":1,"1_1":1,"2_0":0,"2_1":0,"3_0":2,"3_1":2,"4_0":3,"4_1":3,"4_2":3,"4_3":3,"5_0":"chest","5_1":"chest","5_2":"chest"}},{"id":"gos","n":"Garden of Salvation","type":"Raid","players":"6","loc":"The Black Garden (from the Moon)","rel":"Shadowkeep (October 2019)","intro":"A Vex raid that chases the Unknown Artifact's signal through the Black Garden. Four encounters built on tethers (linking Vex boxes with your Light), Voltaic motes and the Enlightened buff, which breaks white shields.","basics":["Tether: walking into a Vex box's beam links you to it. Chain players together to stretch a tether to a far point.","Enlightened: a buff from tethering (or from depositing motes) that breaks white-shielded enemies.","Voltaic Overflow: an orb the boss drops roughly every minute. Someone must pick it up within a few seconds or the team wipes. The picker gets a 2:30 timer; picking up another before it ends kills them."],"enc":[{"n":"Evade the Consecrated Mind","kind":"enc","goal":"Chase the Consecrated Mind through three rooms and a final field until it runs off.","steps":["Start: tether from the floating Vex box to the door to open it.","Split: three players stay with the boss in the first room, killing enemies and catching each Voltaic Overflow. Three push ahead to the next barrier.","At each barrier the forward team kills the Angelic Hydra, which unlocks a Vex box, and tethers the barrier open. The boss moves up and the back team leapfrogs past it.","Room 2 needs three people on one tether; room 3 needs three tether boxes.","Final field: sprint toward the back while picking up the last Overflows. Cyclops and Overload Minotaurs are in the field; deal with them so at least one player reaches the end. The encounter ends when the Consecrated Mind leaves."],"tips":["Killing the Cyclops at a gap spawns two or three more in the boss room, so the back team should be ready.","Overload Minotaurs only take real damage after being stunned with Overload rounds."],"wipes":["A Voltaic Overflow nobody picks up.","A second pickup while your 2:30 timer is running kills you."],"chal":{"n":"Leftovers (Staying Alive)","d":"Do not kill spawning Cyclopses (the Cyclopses in the first two rooms)."}},{"n":"Summon the Consecrated Mind","kind":"enc","goal":"Charge the four corner relays and then defend the center relay to draw out the Consecrated Mind.","steps":["Kill the three Goblins in the center before they upload.","The relays sit in a diamond. Charge each corner relay by killing the Angelic Hydra and tethering its Vex box, leaving one player behind to defend it. Two floaters help where needed.","Each relay is attacked by a wave of three Angelic Hydras (one per hallway); the message \"Undergrowth defenses deployed\" means an attack is coming. Vex portals between tethered pairs let you move quickly.","Tether a relay to refresh it after Vex upload into it and to refresh Enlightened (44 seconds). Barrier Hobgoblins in the halls need Anti-Barrier rounds.","After all 12 Angelics die, the center barrier drops. Everyone moves to the center relay and defends it through three waves, refreshing Enlightened by tethering between waves."],"wipes":["Three Vex sacrifices at a relay wipe the team (tethering resets the count)."],"chal":{"n":"A Link to the Chain","d":"All fireteam members must link (receive the enlightened buff) at the same time."}},{"n":"Defeat the Consecrated Mind","kind":"enc","goal":"Bank 30 motes to draw the boss to the relay, break its red eyes, and shoot its weak point.","roles":["Mote team (three): kill the Minotaur that comes down the marked hallway, collect the motes it drops (10 max each) and bank them at the relay. Banking gives Enlightened.","Eye team (three): follow the boss. One player picks up its Voltaic Overflow and is detained; they call which three red eyes are real (the inner three or the outer three) and the other two shoot them."],"steps":["Tether the center relay from the south hallway to start.","The relay moves between four points, marked by a light beam. A Minotaur comes down that hallway; kill it for motes.","Motes expire after 60 seconds. Clear the Goblins too: sacrificing Goblins steal motes, and a second Minotaur only spawns once they are dead.","When three eye-team players all have the Overflow debuff, swap one with a mote runner.","Once 30 motes are banked, the message \"The Consecrated Mind is drawn to the overloaded relay\" appears."],"dps":"Everyone follows the boss to the relay. Destroy all of its red eyes to expose the weak point, then shoot the weak point as it backs down the hallway. Repeat until it dies.","wipes":["A detained player dies if the three correct eyes aren't destroyed in time.","An Overflow nobody picks up wipes the team."],"chal":{"n":"To the Top","d":"Always deposit 10 motes at a time."}},{"n":"Defeat the Sanctified Mind","kind":"enc","goal":"Fill both active relays with 30 motes from the side islands, break the two plus symbols with tethers, then damage the boss.","roles":["Two mote teams take turns on the side islands.","Platform team stays on the main platform, rebuilds platforms and kills the Cyclops."],"steps":["Shoot the boss to start, kill the spawned enemies, and destroy the Angelic Hydra to unlock the relays.","Two relays are active at a time: left relays are always blue, right relays always orange. Motes are color-coded to their relay and expire after 60 seconds.","Shoot the boss's red weak point on its shoulder or knee to stun it and open a portal on that side. A mote team goes through within about 10–15 seconds to an island, collects about 15 motes, and comes back when the weak point is shot again. Each time, a Cyclops spawns that the platform team kills.","Deposit the motes in the matching relay. Depositing gives Enlightened, which breaks white shields in one bullet.","When the boss lowers its hand, a platform breaks. Rebuild it by tethering from the relay to the plus symbol on the ground. Standing on a platform when it breaks kills you.","When each relay holds 30 motes, the boss shows a blue or orange plus above its hand. Tether from the matching relay to break it, then immediately tether from the other relay to break the second."],"dps":"The boss drops and exposes its weak point (the stomach). Group in front of it and damage it while it stands and then hovers. It enrages after four rotations; there is no final stand.","wipes":["Missing the second tether ends the damage chance and restarts the rotation.","The boss enrages and wipes the team after its fourth rotation."],"chal":{"n":"Zero to One Hundred","d":"Fill each bank (conflux) with 30 motes, within 10 seconds of initially depositing the first set of motes."}}],"chests":["After Evade: drop through the large hole in the room and go left. Jump across the leaves and branches to the pillar with the moving elevator; jump under the elevator into the hole beside it to reach the chest.","Before the Sanctified Mind: after the door, go left instead of taking the portal. Follow the ledge and curved wall to the rotating wheels and jump through both. After the second wheel, look up for a path and climb to the top. Head right to the large tree and take the left entrance; go to the back of the left room and turn around. The chest is above you; jump up the stumps."],"loot":{"Evade the Consecrated Mind":["Zealot's Reward","Accrued Redemption","Leg armor"],"Summon the Consecrated Mind":["Prophet of Doom","Reckless Oracle","Gauntlets"],"Defeat the Consecrated Mind":["Ancient Gospel","Sacred Provenance","Chest armor"],"Defeat the Sanctified Mind":["Omniscient Eye","Helmet","Class item"]},"lootNote":"Divinity (exotic trace rifle) does not drop. It comes from a long quest that runs through the raid.","src":[["PowerPyx: Garden of Salvation walkthrough","https://www.powerpyx.com/destiny-2-garden-of-salvation-raid-walkthrough/"],["Shacknews: Garden of Salvation raid guide","https://shacknews.com/article/114369/garden-of-salvation-raid-guide-destiny-2"],["Shacknews: Garden of Salvation loot table","https://shacknews.com/article/137416/garden-salvation-loot-table-destiny-2"],["Kyber's Corner: raid challenges","https://kyberscorner.com/destiny2/raid-challenges/"]],"b":"Garden of Salvation","k":["Garden of Salvation"],"pl":{"1_0":0,"1_1":0,"2_0":2,"2_1":2,"3_0":3,"3_1":3,"3_2":3}},{"id":"kf","n":"King's Fall","type":"Raid","players":"6","loc":"The Dreadnaught (Saturn)","rel":"Season of Plunder (August 2022); originally The Taken King (2015)","intro":"A Hive raid aboard Oryx's Dreadnaught, brought back from Destiny 1. Its core idea is passing Brands and Auras between players at exactly the right time. Encounters: opening the gate, Totems, the Warpriest, Golgoroth, the Daughters of Oryx and Oryx, the Taken King, with jumping puzzles in between.","enc":[{"n":"Opening the gate (Relics)","kind":"enc","goal":"Carry the relic orbs to the statues on both sides until the portal opens.","steps":["Split into two groups of three, one per side.","One player per group picks up an orb, which seals the doors back to the statues. The others kill enemies and break the door barriers.","Deposit the orb at the statue, then collect the next one. Each orb is farther away than the last.","Relics expire if held too long; each deposit adds about 3 seconds.","When all orbs are in, clear the court near the portal to activate it."]},{"n":"Hive ship jumping puzzle","kind":"trav","goal":"Jump from ship to ship to the far side.","steps":["Ride and jump between the moving Hive ships to the end. Unchanged from Destiny 1."]},{"n":"Totems","kind":"enc","goal":"Keep a player under both Annihilator Totems at all times while the Brands rotate, and drain Deathsinger's Power in the center. No boss.","steps":["Three rooms: left, center and right. One team of three takes each side room.","Picking up the orb in a side room gives Brand of the Unraveler or Brand of the Weaver, with a 30-second timer. If it runs out before you pass it on, you die.","The Brand holder stands on the plate under the totem and gets kills to build Deathsinger's Power.","A teammate kills the Wizard on the center balcony, then the Blightguard that spawns. It drops Brand Claimer: carry it to the Brand holder and interact to take the Brand.","The former holder takes their Deathsinger's Power to the center plate and stands there until it drains.","Rotate roles and positions until the encounter ends."],"wipes":["If nobody stands below an Annihilator Totem, the team wipes after a few seconds."],"tips":["Don't kill center-room enemies unless they attack you; more enemies reaching the side rooms means more charges.","Unstoppable Ogres spawn at the center plate a couple of times."],"chal":{"n":"The Grass is Always Greener","d":"Guardians must not take the same buff type (Brand of the Unraveler or Brand of the Weaver) twice in a row."}},{"n":"The Warpriest","kind":"enc","goal":"Read the glyph sequence on the three plates to earn Brand of the Initiate, then damage the Warpriest inside its aura.","steps":["Stand on the middle plate to start. Kill enemies until Revenant or Ravenous Taken Knights spawn, which starts the glyph sequence.","\"Glyph reading sequence started\": from the middle plate, check the left and right monoliths. If neither glows, the middle plate is first; otherwise the glowing monolith marks the first plate.","\"Glyph sequence started\": stand on the first plate, find the next glowing monolith, and fill the second then the third plate, staying on each until all three are held.","You can only see the backs of some monoliths from each plate (the middle sees the backs of left and right; the left sees the back of right; the right sees the back of left), so use elimination.","The player on the third plate gets Brand of the Initiate. Group up inside its aura to damage the Warpriest.","Blightguards spawn where the Brand wasn't picked up. Different players fetch Brand Claimer from them and bring it back before the Brand's timer reaches zero (two runs per phase)."],"dps":"Damage from inside the aura, between the middle and right monoliths so the Warpriest's head stays visible. When the phase ends, hide behind a monolith from the Oculus; it absorbs that monolith. There are at most four damage phases.","chal":{"n":"Devious Thievery","d":"Guardians have five seconds to swap buffs after grabbing the Taken Knight's Buff Claimer effect."}},{"n":"Golgoroth's Maze","kind":"trav","goal":"Get through the dark maze to Golgoroth.","steps":["A short maze section before the boss; the second hidden chest is here (see Hidden chests)."]},{"n":"Golgoroth","kind":"enc","goal":"Hold Golgoroth's Gaze in turns while the team damages his belly from the pools, without letting orbs go to waste.","roles":["Two Gaze holders trade Golgoroth's Gaze.","The other four destroy orbs and damage from the Pools of Reclaimed Light."],"steps":["Destroy the central orb to summon Golgoroth, then clear enemies down the sides until an orb spawns.","A Gaze holder takes Golgoroth's Gaze by shooting him in the back. It lasts 20 seconds; he fires at the holder instead of killing the players at his feet. The second holder takes it over before it ends.","The damage team destroys an orb, stands in the Pool of Reclaimed Light it creates, and shoots his stomach. When the Gaze changes hands, destroy the next orb.","Unstable Essence lands on a random player in a pool and explodes after a few seconds, killing anyone nearby. Move away from your team (staying near the boss damages him)."],"dps":"The damage phase ends when all six orbs are used or a Gaze transfer fails. Regroup on the edges and clear the new enemies. Each unused orb adds a Tablet of Ruin mark; six marks wipe the team. At most three full rotations.","chal":{"n":"Gaze Amaze","d":"The player with Golgoroth's Gaze must be standing in the Pool of Reclaimed Light when the Gaze is swapped."}},{"n":"Piston wall jumping puzzle","kind":"trav","goal":"Cross along the wall of pistons to the Daughters.","steps":["Work your way along, across and back along the piston wall. The third hidden chest is here."]},{"n":"Daughters of Oryx","kind":"enc","goal":"Build the Ascendant path so the Torn player can collect the Blightguard three times, steal the singing Daughter's aura, and kill her inside it. Then the other Daughter.","steps":["Kill the Knight on the starting platform and jump up to it. Call out where the floating symbol is: it marks the second platform. Standing on the two correct platforms forms the Ascendant path.","One random player is Torn Between Dimensions and is the only one who can use the floating blocks of the path. They cross it to collect a Blightguard piece. Do this three times; on the third they interact to take the Blightguard.","The Torn player goes under the Daughter who is shooting and interacts to take her aura (Aura of Unraveling or Aura of Weaving). Everyone groups inside the aura and damages her.","Repeat for the second Daughter."],"wipes":["One Daughter sings Dirge of Unraveling or Hymn of Weaving for two minutes, then wipes the team. Only stealing the shooting Daughter's aura stops it. Each phase gives two minutes for all three Blightguard runs, the steal and the kill."],"tips":["Clear the platform to the right of the entrance quickly: four Taken Phalanx spawn there. Snipers appear on the floating side islands when the second platform activates.","Damage from the small ledge in the middle, opposite the Daughter you are attacking. One player per platform, with two floaters."],"chal":{"n":"Under Construction","d":"Guardians must not stand on the same plate twice. The Torn player doesn't count."}},{"n":"Oryx, the Taken King","kind":"enc","goal":"Set up Corrupted Light bombs from the Light-Eater Ogres, detonate them together while standing in the Aura of Immortality, and damage Oryx while he is stunned.","steps":["Approach the wisp at the front of the room and kill enemies until Oryx slams a platform: that is the starting platform. Standing on it picks the Torn player and shows the finishing platform.","Four Light-Eater Ogres spawn, one beside each platform; each drops a Corrupted Light bomb. A Light-Eater Knight then runs from diagonally across toward each bomb and deletes it if it touches it. Kill the Knights.","The Torn player collects Blightguard pieces three times, as in the Daughters fight; the third time they get Brand Claimer.","Take the Aura of Immortality from the Vessel of Oryx Knight running down the middle of the room, then kill the Knight.","When \"Oryx calls upon the darkness\" appears, everyone crosses into the center of the wispy circle so all bombs detonate together, while standing in the Aura of Immortality to survive."],"dps":"Each bomb adds seconds to the damage window. Shoot Oryx's chest while he is stunned. Afterwards he either summons bombs on players at the front of the ship (run laps, or kill the four Taken Knights on the platforms to end it early) or pulls players one at a time into a dome to fight his Shade. Repeat until Oryx reaches 25%. Final stand: two more Light-Eater Ogres drop Corrupted Light and no Knights spawn; detonate both when he calls the darkness and damage his glowing chest.","chal":{"n":"Hands Off","d":"Players must not kill the same Ogre or Light-Eater Knight throughout the encounter. (Knights on the plates don't count.)"}}],"chests":["Ship jumping puzzle: from the second docked Hive ship, find the hole in the left-side wall across from you. Ride the ship to a spiky platform just before it docks and jump onto it, then follow the narrow path out of the wall. The door opens once players have stood on the last two plates in the jumping puzzle.","Golgoroth's Maze: stand on the five plates in this order: bottom right, top left, bottom left, middle left (reached by climbing the ceiling), top right. A chest spawns near the center of the maze.","Piston wall: continue until you see a group of Taken Vandals and stand directly across from them. Use your Ghost to reveal hidden platforms and follow them, scanning again at dead ends. Climb a nearby pillar, find the next platforms, and reach a hole in the wall to the hidden room."],"extra":{"t":"Deepsight symbol chest","b":["Nine Hive symbols are hidden around the Dreadnaught; activating the right three spawns a guaranteed Deepsight chest. The three to use are shown under the exit of the opening section.","Locations: Double Dash (at the swinging pendulums, jump on the first and turn around); Spider (above the doorframe at the first hidden chest); Spider with V legs (Totems, on cover near the left totem, look left); Jellyfish (Warpriest, from the left plate look right); Triple Dots (end of Golgoroth's Maze, turn around at the exit pit); X (Golgoroth, drop from the rally banner and turn left); Neutral Face (left of the third hidden chest); Ice Cream (end of the last jumping puzzle, look up from the Daughters doorway); U (Daughters/Oryx arena, above the entrance)."]},"loot":{"Totems":["Doom of Chelchis","Qullim's Terminus","Chest armor","Leg armor","Class item"],"The Warpriest":["Smite of Merain","Defiance of Yasmin","Gauntlets","Chest armor"],"Golgoroth":["Zaouli's Bane","Midha's Reckoning","Qullim's Terminus","Helmet","Leg armor"],"Daughters of Oryx":["Smite of Merain","Zaouli's Bane","Gauntlets","Chest armor"],"Oryx, the Taken King":["Any weapon or armor from the earlier encounters","Touch of Malice (exotic)"]},"lootNote":"Touch of Malice can drop from Oryx's final chest. Loot tables disagree on a few extra drops for Golgoroth and the Daughters; the drops listed here are the ones they agree on.","src":[["Shacknews: King's Fall raid guide","https://www.shacknews.com/article/131935/kings-fall-raid-guide-destiny-2"],["Shacknews: King's Fall loot table","https://shacknews.com/article/132127/kings-fall-loot-pool-destiny-2"],["Blueberries: King's Fall loot table","https://www.blueberries.gg/weapons/kings-fall-loot-table/"],["TheGamer: King's Fall hidden chests","https://www.thegamer.com/destiny-2-kings-fall-raid-encounters-hidden-chests/"],["Kyber's Corner: raid challenges","https://kyberscorner.com/destiny2/raid-challenges/"]],"b":"King’s Fall","k":["King's Fall"],"pl":{"0_1":"top","0_2":0,"1_0":2,"2_0":3,"3_0":5,"3_1":4,"3_2":4,"4_0":7,"5_0":8,"6_0":"chest"}},{"id":"lw","n":"Last Wish","type":"Raid","players":"6","loc":"The Dreaming City","rel":"Forsaken (September 2018)","intro":"The Forsaken raid inside Riven's lair. Five boss encounters and the Queenswalk: Kalli, Shuro Chi, Morgeth, the Vault, Riven of a Thousand Voices, and carrying Riven's heart out. Any Last Wish weapon can drop from any encounter, and One Thousand Voices drops from the final chest.","enc":[{"n":"Kalli, the Corrupted","kind":"enc","goal":"Match the symbols shown in the center to the plates around the room, kill the Knights they summon, then hide from Kalli's wipe and damage her.","steps":["Pairs of players match the snake symbols shown in the center to the plates around the room.","On each plate, two random sections spawn Taken bombs that kill anyone standing on them; stand on the clear strip. Three explosions (four if something goes wrong) complete the charge and summon a Knight.","Killing that Knight removes its symbol from the center.","Activating a plate whose symbol is not in the center spawns a much stronger Ogre."],"dps":"Starts once all the Knights are dead. When the message \"Kalli prepares to wield her weapon\" appears, hide in one of the safe rooms below her. Each correctly killed Knight unlocks safe rooms, so a missed Knight leaves you fewer places to hide. Psions spawn after each explosion. The hide-and-damage cycle happens three times, then the symbols reset.","roles":["Symbol-matching pairs on the plates.","Knight clearers.","A caller assigning safe rooms."],"chal":{"n":"The Summoning Ritual","d":"Activate and cleanse all nine plates, then kill all nine Knights and Ogres before damaging Kalli."}},{"n":"Shuro Chi, the Corrupted","kind":"enc","goal":"Break Shuro Chi's shield, take her health down, and solve the button puzzle on each of the three levels before the 4-minute timer runs out.","steps":["Each level has a 4-minute timer. Finishing the puzzle room resets it; failing to finish in time wipes the team.","Kill the Taken Captain to drop an Eye of Riven. Its Super interrupts Shuro Chi's wipe attack; using it blocks you from picking up another Eye for 90 seconds.","Prism weapon holders pick up the weapon, stand on their plate and shoot the player to their right, forming a triangle that drops her shield. The plates hurt over time, and removing the shield faster saves time.","With the shield down, deal enough damage to remove a health segment. The Eye holder interrupts the wipe with the Super, and you get one more chance to finish the segment.","Puzzle room: nine floor buttons and three wall pictures. Solve the puzzles left to right; each button can be used only once across all three. Buttons hurt over time, so two players should handle enemies."],"tips":["The bottom level has Taken Thrall, the middle Taken Psions and the top Taken Acolytes; every level also has Knights, a Captain and an Ogre.","On the top level enemies keep spawning during damage. A Warlock with Well of Radiance helps a lot here."],"chal":{"n":"Which Witch","d":"Guardians must not get hit or take damage from Shuro Chi's Arc Blast."}},{"n":"Morgeth, the Spirekeeper","kind":"enc","goal":"Keep Morgeth from reaching 100% strength by collecting every Taken Strength, then shoot his back.","steps":["Taken Strength pillars spawn around the arena. A player can hold two; a third kills them.","A player holding two can be locked in place by Umbral Enervation and must be cleansed within 20 seconds or die.","To cleanse: a player with no Taken Strength kills an Eye of Riven, picks up the Taken Essence and uses its grenade on the locked player. The Taken Strength moves to the cleanser, so the cleanser must have room for it.","After the last Eye of Riven dies, a final Taken Strength spawns in front of Morgeth. The player with the fewest stacks takes it while someone else takes the Taken Essence."],"dps":"The other players group at the far side and shoot Morgeth's back (his crit spot) and the homing orbs. The Taken Essence holder uses the Super at 90% strength to interrupt the wipe. 100% wipes the team.","tips":["Taken Essence stays on the ground for 45 seconds. Holding it builds Taken Essence Antumbra stacks, which kill at x10. After a successful cleanse the holder can't pick it up again for 90 seconds."],"roles":["Two Taken Strength collectors.","One cleanser.","Everyone else on damage."],"chal":{"n":"Forever Fight","d":"Do not kill the smaller Ogres."}},{"n":"The Vault","kind":"enc","goal":"Cleanse the three locks with the right Taken Essence before the three-minute timer runs out. No boss.","steps":["Three arenas (Tree, Ball, Rock) surround the central lock. A player stands on each lock; each shows three symbols. The middle symbol is the real one; the symbols beside it can be duplicates.","Penumbra cleanses a duplicate on the left; Antumbra cleanses a duplicate on the right. The wrong essence explodes and kills the holder and anyone nearby.","After an Eye of Riven dies, two arenas are sealed by Taken barriers and the essence holder runs through the tunnels to the lock.","Meanwhile Might of Riven Knights walk toward the lock: one, then two, then three each round (resetting after all three locks are cleansed). A Knight that holds a lock wipes the team.","Each full cycle sends up a beam of light; three beams open the Vault."],"chal":{"n":"Keep Out","d":"Ensure that no Might of Riven knights make it into the center chamber during the Vault fight."}},{"n":"Riven of a Thousand Voices","kind":"enc","goal":"Cleanse the symbols, shoot the eyes Riven shows you, take her down to her final stand, then destroy her heart.","steps":["Split into two groups of three, one in the blue room and one in the yellow room. Each room sees either Riven or an Eye of Riven, in a varying order.","If you see Riven: call out which eyes glow. If you see an Eye of Riven: cleanse the correct symbol, with the player behind the glass directing the essence holder.","Damage Riven's tentacles or mouth to stagger her, which makes two eyes glow. In the damage phase, shoot the Taken orb in her mouth, then destroy the called eyes in time or the team wipes.","On the top level, six eyes glow across three staggers. Each player remembers one. When Riven appears a fourth time with a Taken orb in her mouth, each player destroys their eye.","As she descends, shoot the glowing weak points; each takes a large chunk of health.","You are pulled into the Ascendant Plane for a short jumping section. Ascendant Atrophy stops health regeneration and drains health. One player touching the light at the top brings everyone back."],"dps":"Final stand: Riven opens her mouth to show a Taken orb. Damage her until she dies, then run into her mouth and destroy the Taken Blight while Metaphysical Bleed slowly kills you.","chal":{"n":"Strength of Memory","d":"Guardians must not shoot the same Riven eye twice."}},{"n":"Queenswalk (Heart of Riven)","kind":"enc","goal":"Carry Riven's heart back through the lair to the offering point. Ends the raid.","steps":["A random player becomes the heart carrier (Fate's Chosen) with a 15-second countdown; when it ends they are pulled into the other realm and a new carrier is chosen.","Everyone else builds Creeping Darkness, which kills at x10. Only standing in the carrier's aura removes it, and the aura shrinks over time.","The carrier can pick up the Taken Strength orbs along the route (two at a time). Picking up the last one slows the heart and resets the carrier's timer, once per carrier. Enemies, including Mights of Riven, keep spawning.","Route: leave Riven's mouth, go left through the door, cross the crumbled room avoiding the poisonous floor, circle the Vault through the tunnels, drop through the hole, then climb the lit stairs to the basin below Riven's statue. The heart is dunked automatically."]}],"chests":["Wish 2 on the Wall of Wishes spawns a chest between Morgeth and the Vault, opened with a Glittering Key.","Wish 1 grants an Ethereal Key for an extra chest at the end of the raid (one per account, per Destinypedia)."],"extra":{"t":"Wall of Wishes","b":["The Wall of Wishes accepts 15 wishes, entered as patterns on its 21 buttons.","Wishes 4 to 7 wipe the fireteam and teleport it to a later encounter: 4 Shuro Chi, 5 Morgeth, 6 the Vault, 7 Riven.","Wish 13 (Petra's Run): if anyone dies, the whole team is sent to orbit (needed for the Petra's Run triumph).","Other wishes change voices or music, add effects (Grunt Birthday Party), or unlock an emblem."]},"lootAll":["Age-Old Bond","Apex Predator","Chattering Bone","Nation of Beasts","Techeun Force","The Supremacy","Transfiguration","Tyranny of Heaven","Helmet","Gauntlets","Chest armor","Leg armor","Class item"],"lootNote":"Every encounter drops from the whole pool; each also has a set curated roll: Age-Old Bond (Kalli), Transfiguration (Shuro Chi), Nation of Beasts (Morgeth), Tyranny of Heaven (Vault), Chattering Bone (Riven). One Thousand Voices (exotic) drops only at the end. Completing certain triumphs raises its drop chance: Petra's Run, Thunderstruck, Night Owl, Sunburn, The New Meta, Coliseum Champion, Forever Fight, Keep Out and Strength of Memory.","src":[["Shacknews: Last Wish raid guide","https://shacknews.com/article/107313/destiny-2-last-wish-raid-guide"],["Shacknews: Last Wish loot table","https://shacknews.com/article/135660/last-wish-raid-loot-table-destiny-2"],["Destinypedia: Last Wish","https://www.destinypedia.com/Last_Wish"],["Kyber's Corner: raid challenges","https://kyberscorner.com/destiny2/raid-challenges/"]],"b":"Last Wish","k":["Last Wish"],"pl":{"0_2":"top","0_3":"rest","1_0":0,"1_1":0,"2_0":1,"3_0":3,"3_1":3,"4_0":4,"4_1":4,"4_2":4,"4_3":4,"4_4":4}},{"id":"ron","n":"Root of Nightmares","type":"Raid","players":"6","loc":"Neomuna (Neptune)","rel":"Lightfall (March 2023)","intro":"A Witness-themed raid inside the Pyramid ship over Neptune. Every encounter uses two buffs you get by shooting orbs: Field of Light and Flux of Darkness. Build node networks with them, sort planets for Zo'Aurc, and survive Nezarec's wipes with the right Refuge.","basics":["Field of Light and Flux of Darkness: stand near a lit node and shoot its orb to give the buff to everyone nearby. A buff is used up when it activates the next node of the same color.","Refuge: holding Light and then taking Darkness gives Darkness Refuge; the reverse gives Light Refuge. It protects you from a wipe attack of the matching type."],"enc":[{"n":"Cataclysm","kind":"enc","goal":"Complete the Light node networks before Sweeping Terror runs out, extending it by killing Tormentors.","roles":["Two players build the network.","Everyone else clears enemies and kills Psions."],"steps":["Stand in a completed node's aura and shoot it to get Field of Light (15 seconds). Find the next node, stand on its plate and shoot its orb to activate it, which uses up the buff. Repeat until the network is complete. There are roughly four networks of five to seven nodes.","Sweeping Terror is a 33-second countdown that wipes the team at zero. Completing a network halts it (\"His hatred halts\").","Two shielded Psions spawn; killing both spawns a Tormentor. Killing the Tormentor adds 35 seconds to Sweeping Terror.","Only refresh Field of Light after a node is activated: refreshing early takes the buff away from players who already hold it.","Barrier Colossi spawn throughout."],"wipes":["Sweeping Terror reaching zero."],"chal":{"n":"Illuminated Torment","d":"Tormentors can only be killed by Guardians with the Field of Light buff."}},{"n":"Scission","kind":"enc","goal":"Build a Darkness network on the left and a Light network on the right, crossing the gap with launchers, across three levels.","steps":["Split into two groups of three: the left side uses Flux of Darkness, the right side Field of Light.","The gap jumper takes the buff, shoots the shard at the launcher to cross, activates the node, then comes back to refresh and continue.","Redolence of Splendor can only be damaged with Field of Light, Redolence of Decay only with Flux of Darkness. A buff can't activate a node of the other color.","Imminent Expulsion is a wipe timer that goes away once both networks are done.","When a network is complete, a Major Redolence spawns and Barrier Colossi appear on the far side. Killing the Major gives a shard for the launcher at the end, which sends the team to the next level. There are three levels."],"tips":["Have a clearing player grab the buff and activate the next node while the gap jumper comes back."],"wipes":["Imminent Expulsion reaching zero."],"chal":{"n":"Crossfire","d":"Guardians must not shoot launcher crystals on their own side."}},{"n":"Macrocosm: Zo'Aurc, Explicator of Planets","kind":"enc","goal":"Sort the planets so each side has the right colors, match the center planets, then damage Zo'Aurc from the plates that match his shield.","roles":["Four planet swappers (two on the close platforms, two on the far ones).","Two players clear enemies."],"steps":["Kill the Honored Centurions to spawn Terrestrial Lieutenants. The player who kills a Lieutenant gets Planetary Insight, which shows the planet colors on that side.","The right side should hold two Light planets and the left side two Darkness. Call out the odd planet on your side. Stand under it to take it, then place it on the odd planet on the opposite side, in the corner matching where your partner took theirs.","When every planet is swapped, \"The indexed planets reveal themselves\" confirms it.","Kill more Centurions and Lieutenants. The three center planets are two Light and one Darkness, or two Darkness and one Light. Bring a matching side planet to each center planet's floor plate.","Shoot the floating shard to start damage. If a planet was missed, the shard sends you back to the Centurion/Lieutenant phase."],"dps":"Zo'Aurc's shield alternates between Light and Darkness, starting and ending on the majority color. Stand on a plate that matches it; standing below planets also gives a 7-second Field of Light or Flux of Darkness that boosts boss damage. Deal enough damage to reach the notch on each plate or you lose that plate. He is immune after three plates, and the cycle repeats. Move out of his wall-of-flame attack.","chal":{"n":"Cosmic Equilibrium","d":"Guardians must move all Dark planets to the left side and all the Light planets to the right side."}},{"n":"Nezarec, Final God of Pain","kind":"enc","goal":"Build the Light and Darkness networks while keeping Nezarec stunned or taking the right Refuge, then damage him on a platform.","roles":["Two players build networks: Light on the left, Darkness on the right.","Players to break Nezarec's weak points and stun him.","Add clear."],"steps":["While Nezarec is on his platform, break the crit spot on each shoulder. The second break shows a burst of Light or Darkness: note it. Shooting his chest then makes him roam and keeps his attention away from the network players.","Stun him by shooting his chest when he roams. If he isn't stunned, he wipes the team unless everyone stands in the right Refuge.","Refuge: a Dark shoulder means take Field of Light to a Darkness node to make Darkness's Refuge; a Light shoulder means take Flux of Darkness to a Light node to make Light's Refuge. Use a node that's already lit. The Refuge lasts 15 seconds and blocks the wipe but not his other attacks. If you use it, he goes back to his platform and the shoulders have to be broken again.","Once both networks are connected and he is hit by a beam, the damage phase starts."],"dps":"Group on a platform near the edge with Well of Radiance or Ward of Dawn and deal damage; debuff him with Shadowshot or Void weaken grenades. Reset when he turns immune. Later phases are tighter, so build faster or prepare a Refuge. Final stand: knock his health down before he wipes the team; save Heavy or a Super for it.","chal":{"n":"All Hands","d":"All fireteam members must activate a Light node AND Dark node, every dps phase."}}],"chests":["Between the first and second encounters: climb the white roots upward. Look up and to the right for a small alcove leading to a room. Follow the hallway, head right and go down the stairs. Kill the Tormentor and other enemies in the room ahead, then go up the short flight of stairs. The chest is there, with a giant Winnower figure behind it.","Between the second and third encounters (jumping section): time it so everyone has Darkness Refuge, since the waves otherwise wipe the team. Jump onto the low platform near the door toward the third encounter and shoot the crux to open a door nearby. Turn around, go up the stairs and enter the temple. The chest is in the middle of the room, near some Light and Darkness refuge points."],"extra":{"t":"Puzzle chest","b":["Three puzzles (before the first encounter, between the first and second, and right before Nezarec) unlock a bonus chest at the end with a guaranteed Deepsight Root of Nightmares weapon."]},"loot":{"Cataclysm":["Nessa's Oblation","Koraxis's Distress","Briar's Contempt","Helmet","Gauntlets","Chest armor"],"Scission":["Nessa's Oblation","Acasia's Dejection","Mykel's Reverence","Gauntlets","Chest armor","Leg armor"],"Zo'Aurc":["Koraxis's Distress","Rufus's Fury","Mykel's Reverence","Chest armor","Leg armor","Class item"],"Nezarec":["Acasia's Dejection","Rufus's Fury","Briar's Contempt","Helmet","Leg armor","Class item","Conditional Finality (exotic)"]},"lootNote":"Conditional Finality is a rare drop from Nezarec. Completing the Living Nightmares triumph (finish the encounters without anyone dying) greatly raises its drop rate.","src":[["Shacknews: Root of Nightmares raid guide","https://shacknews.com/article/134475/root-of-nightmare-raid-guide-destiny-2"],["GGRecon: Root of Nightmares encounters","https://ggrecon.com/guides/destiny-2-root-of-nightmares"],["Kyber's Corner: Root of Nightmares loot","https://kyberscorner.com/destiny2/root-of-nightmares-raid-loot/"],["Destructoid: Root of Nightmares hidden chests","https://www.destructoid.com/all-hidden-chest-locations-root-of-nightmares-raid-destiny-2/"],["Kyber's Corner: raid challenges","https://kyberscorner.com/destiny2/raid-challenges/"]],"b":"Root of Nightmares","k":["Root of Nightmares"],"pl":{"1_0":0,"2_0":2,"3_0":1,"4_0":3}},{"id":"se","n":"Salvation's Edge","type":"Raid","players":"6","loc":"The Pale Heart (the Monolith)","rel":"The Final Shape (June 2024)","intro":"The Final Shape raid inside the Witness's Monolith. Its language is shapes: collect Resonance (spheres, pyramids, cubes), lock Conductors by bouncing signals between plates, build 3D shapes in Verity, then break the Witness's glyphs and survive its shape tests.","basics":["Resonance: shape buffs you collect and deposit. Holding too many, or letting the Final Shape Looming timer run out, kills you.","Conductors: locked by shooting the center node and standing on the plate the signal reaches.","Stolen Favor: lets the holder see the shape a Conductor needs."],"enc":[{"n":"Substratum","kind":"enc","goal":"Lock six Conductor pillars by running laps of the outer rooms and bouncing signals between plates, while depositing Resonance to keep Final Shape Looming from running out.","roles":["Two teams of three: one goes clockwise, one counter-clockwise.","In each team: one player stays with the active plate, one goes to the Conductor room, one floats and kills enemies."],"steps":["You can hold three Resonance shapes; picking up a fourth kills you. Deposit them in the central box to extend Final Shape Looming.","To lock a Conductor, shoot the center node, then stand on the plate the signal reaches.","A plate that receives a signal and isn't stood on within a few seconds spawns Subjugators.","Killing a Hydra unlocks a door for the other team. Killing the Champion (a Minotaur in the third room) opens the door back to the center and spawns a Tormentor, which locks the rooms again.","Three rotations lock all six Conductors. After both Conductors in a rotation lock, a Subjugator spawns in the center; kill it to summon the box. The encounter ends once everyone has deposited their Resonance."],"wipes":["Final Shape Looming reaching zero.","Picking up a fourth Resonance shape (kills you)."],"chal":{"n":"Scenic Route","d":"Only eliminate the Overload champion that spawns in the fourth room."}},{"n":"Dissipation: Herald of Finality","kind":"enc","goal":"Lock three Conductors with matching Resonance, deposit to start damage, and kill the Herald.","roles":["Three teams of two, one in each section (middle, left, right)."],"steps":["Resonance comes as Pyramidal or Spherical; the last shape you collect sets the type of your whole stack.","One player per side gets Call to Reckoning. Only they can damage the Herald's head. Headshots summon Blights; destroying them lets them shoot the head again for Stolen Favor.","Stolen Favor shows the shape on the Conductor. The player who locks it needs the matching Resonance.","Each section has Attendants, Taken Knights, Trammel minibosses and a Wizard, Centurion or Ogre. A plate that receives a signal and isn't stood on summons a miniboss.","With all three Conductors locked, a box spawns in the pit. Depositing Resonance extends Final Shape Looming and starts the damage phase."],"dps":"When the Herald turns immune, go back to your sections and repeat. At its last chunk the damage phase extends and Taken enemies spawn. Don't go into the final stand without enough time left on the encounter timer.","chal":{"n":"At Capacity","d":"Fireteam members who deposit resonances must deposit 3 stacks at a time."}},{"n":"Repository","kind":"enc","goal":"Clear three rooms, each with three Conductors (triangle, circle, square), by sending signals between plates and locking each Conductor with matching Resonance.","roles":["Three pairs, one per lane."],"steps":["The player who kills the Tormentor in each lane gets Stolen Favor and can see the Conductor's shape.","Collect the Resonance shapes from your plates, then lock the matching Conductor. A plate's shape may not match its own Conductor, so you may need to switch lanes.","Clear enemies and kill the Champion to unlock the door to the next room.","Later rooms work the same way, but the layout differs and plate signals can cross over."],"chal":{"n":"Balanced Diet","d":"Guardians cannot pick up the same shape buff twice in a row."}},{"n":"Verity","kind":"enc","goal":"Free the three players trapped in the statue rooms by matching shapes inside and outside. Do it three times, then the final revive.","roles":["Outside (three players together): build a 3D shape on each statue that matches the trapped player's pocket shape.","Inside (three solo players): collect the two 2D shapes your statue isn't holding, forming a 3D shape in your pocket."],"steps":["A 3D shape is two 2D shapes combined. Outside, swap shapes between statues by depositing a 2D shape on a statue. Knights and Ogres drop 2D shapes.","Inside, the shadow shapes on the walls show which shapes the Knights dropped. Depositing a Knight's shape on the statue sends it to that statue's solo player; each shape sent summons an Ogre.","When a statue's outside 3D shape matches its inside player's pocket shape, that player walks through the wall and rejoins the outside team.","Catatonic Decimation: the Witness kills inside players at random. Outside players revive them by bringing the correct Ghost to the matching statue.","After all solo players are freed and the Unstoppable Ogres are dead, the last player alive revives the team using the same Ghost-to-statue matching."],"wipes":["Placing a Ghost at the wrong statue kills that player."],"chal":{"n":"Varied Geometry","d":"Guardians cannot use the same 3D shape consecutively."}},{"n":"Zenith: The Witness","kind":"enc","goal":"Get Glyphbreaker, destroy the Witness's six glyphs, pass its shape tests, then damage it.","steps":["Glyphbreaker (needed to destroy glyphs): stand in an arm's attack and shoot its bracelet, collect the Resonance it reveals, then stand in an arm attack again and shoot the bracelet again.","Arm attacks: arm up = bees at a circle (Spherical); arm down = triangles (Pyramidal); arm sideways = beam (Hexahedron). Bracelet colors: red = Hexahedron, yellow = Spherical, green = Pyramidal. A bracelet never shows its own arm's color.","Each destroyed glyph spawns a Subjugator, so break three at once to limit spawns.","Witness tests: 14 Resonance nodes appear. Shoot the extras so the rest form the shape of the arm most recently shot for Glyphbreaker (a beam arm means a square). An audio cue (a screaming arm) hints the shape. Jump over the pulse that follows."],"dps":"After all six glyphs, damage happens on the center platform. The Witness hits a huge area with near-lethal attacks, each followed by its opposite side. After three sets it smashes the plate: jump off first or die. The final stand needs roughly a sixth of its health within the time limit.","wipes":["Making the wrong shape in a test wipes the team.","Staying on the plate during the plate smash kills you."],"chal":{"n":"Coordinated Efforts","d":"Destroy all of the Witness' Glyphs consecutively (within five seconds of each other)."}}],"chests":["After the Herald of Finality (jumping section): head to the south part of the arena and take the red elevator up. Keep climbing to a room with glowing orange stones on the ceiling and two Omen of the Witness Subjugators. Kill them, go to the back of the area and turn left to a wall of yellow stones with a small gap at the bottom. Crouch through it to the chest.","Before the Witness (roots and blocks section): stop before the large doorway to the boss and jump down to the right. Look for an opening in the bottom-right wall from the huge door. The chest is directly below the boss arena."],"loot":{"Substratum":["Imminence","Non-Denouement","Nullify","Gauntlets","Chest armor"],"Herald of Finality":["Forthcoming Deviance","Imminence","Non-Denouement","Summum Bonum","Helmet","Class item"],"Repository":["Critical Anomaly","Forthcoming Deviance","Nullify","Gauntlets","Class item"],"Verity":["Imminence","Non-Denouement","Summum Bonum","Chest armor","Leg armor"],"The Witness":["Critical Anomaly","Nullify","Summum Bonum","Helmet","Leg armor","Euphony (exotic)"]},"lootNote":"Euphony drops from The Witness.","src":[["Shacknews: Salvation's Edge raid guide","https://shacknews.com/article/140025/salvations-edge-raid-guide-destiny-2"],["Shacknews: Salvation's Edge loot table","https://shacknews.com/article/140602/salvations-edge-loot-table-destiny-2"],["Sportskeeda: Salvation's Edge secret chests","https://sportskeeda.com/mmo/all-secret-chest-locations-guide-destiny-2-salvation-s-edge"],["Kyber's Corner: raid challenges","https://kyberscorner.com/destiny2/raid-challenges/"]],"b":"Salvation’s Edge","k":["Salvation's Edge"],"pl":{"1_0":0,"2_0":1,"3_0":2,"4_0":3,"5_0":4,"6_0":2,"6_1":0}},{"id":"vog","n":"Vault of Glass","type":"Raid","players":"6","loc":"Venus","rel":"Season of the Splicer (May 2021); originally Destiny 1 (2014)","intro":"A Vex raid about time and timing. Six encounters plus the Gorgons' Labyrinth: open the Vault, defend the Confluxes, destroy Oracles in order, break the Templar, run Relics through the Gatekeeper portals, then beat Atheon, Time's Conflux.","enc":[{"n":"Opening the Vault","kind":"enc","goal":"Hold three Vex sync plates until the central Spire is built and the Vault door opens.","steps":["Split into pairs, two players on each plate (left, middle, right).","Standing on all three plates starts building the Spire, and Vex begin spawning.","Only Praetorians can sever a plate's connection (the plate turns red). Kill them before they reach a plate; they alternate spawn points.","Cyclops spawn during the fight and hit hard. Knock them down fast with Supers and Heavy.","Once a plate is connected, players can step off it to fight."],"tips":["The Spire grows in the Vex latticework above the arena. When it completes, the enemies despawn and the door opens."]},{"n":"Confluxes","kind":"enc","goal":"Stop the Vex from sacrificing themselves at the Confluxes.","steps":["Phase 1: one Conflux in the middle. Defend it as a group or send players out to clear spawns.","Phase 2: two Confluxes. Split the team in half, one half per side.","Phase 3: three Confluxes, two players at each.","Defending a Conflux makes it disappear and sends a rush of enemies; survive it to reach the next Conflux. Overload Minotaurs rush the area when the Confluxes despawn.","Some Vex explode and leave pools. Standing in one gives Marked for Negation; cleanse it by standing in the central well."],"wipes":["A Wyvern completing its sacrifice wipes the team immediately.","Too many Vex sacrificing also fails the encounter."],"chal":{"n":"Wait for It…","d":"Sacrificial Wyverns cannot die before beginning to sacrifice at the confluxes."}},{"n":"Oracles","kind":"enc","goal":"Destroy the Oracles in the exact order they appeared.","steps":["Rounds show 3, 4, 5, 6 and then 7 Oracles.","Give each player an Oracle spawn to watch. Count the chimes and call your number when your Oracle appears, then again when it is destroyed. With seven Oracles, one player covers two.","Name the spawns before you start (for example L1–L3, R1–R4, mid) so callouts are instant.","Goblins and Minotaurs spawn in the arena, and Hobgoblins snipe from distant blocks."],"wipes":["Destroying Oracles in the wrong order marks the team and eventually wipes it.","Destroying them too slowly also wipes the team."],"chal":{"n":"The Only Oracle for You","d":"Players may not destroy the same oracle twice."}},{"n":"The Templar","kind":"enc","goal":"Break the Templar's shield with the Relic, then damage it. Repeat until it dies.","roles":["Relic holder: destroys at least one Oracle, uses the Relic Super on the shield, and protects the team with the Relic's shield.","Everyone else: help with the Oracles and shoot the Templar's weak point (its \"nose\")."],"steps":["Pick up the Relic to start the fight.","Destroy the three Oracles in the order they spawn.","Use the Relic Super to remove the Templar's shield and free any Detained players.","Damage the Templar until it creates a ring and teleports. It regains its shield, and the steps repeat.","To stop a teleport, the Relic holder stands in the ring until it disappears. Each block spawns Praetorians, so clear them while you keep damaging."],"dps":"Close range from the platforms near the spawn with Ward of Dawn and Well of Radiance, or from far away with Snipers and other Power weapons.","wipes":["If the Relic is dropped and nobody picks it up within 10 seconds, the team wipes."],"chal":{"n":"Out of Its Way","d":"Defeat the Templar without letting it teleport."}},{"n":"Gorgons' Labyrinth","kind":"trav","goal":"Get through the maze without being seen. Not a real encounter, but it can wipe you.","steps":["If a Gorgon sees you, it enrages and wipes the team.","The exit is on the left side of the maze from where you enter.","The most consistent route jumps over the Gorgons using the large rocks on the left side of the main maze area."]},{"n":"The Gatekeeper","kind":"enc","goal":"Relay the Relic through the portals to kill shielded Praetorians until a Conflux appears, then defend it.","roles":["Relic holder: enters the portal with the Praetorian, removes its shield, and drops the Relic for the next player.","Portal players: go through the portals and call out which side has the Praetorian.","Sync plate players: hold the plates that keep the portals open and defend them from Goblins and Overload Minotaurs."],"steps":["Kill the Gatekeeper on the central island and pick up the Relic from the middle.","Stand on the sync plates to open both portals and send one player into each.","Call out the Praetorian. The Relic holder enters that portal, kills it, and drops the Relic for the player inside.","That player carries the Relic out and passes it across the room to the other side, and the process repeats.","A new Gatekeeper spawns on the central island and shuts the portals off; kill it to turn them back on. Six Gatekeepers die in total, counting the first.","When a Conflux spawns in the center, defend it from Praetorians and Wyverns until the encounter ends."],"tips":["Teleport Destabilized (45 seconds) stops a player carrying the Relic through a portal twice in a row, so it has to be passed on.","Overload Minotaurs spawn after the first Gatekeeper. One that reaches a sync plate claims it and shuts down that portal.","Three Wyverns spawn near the end; when a Praetorian appears in one portal, a Wyvern appears on the other side. Burst Supers (Blade Barrage, Thundercrash, Nova Bomb) delete them."],"chal":{"n":"Strangers in Time","d":"The Wyvern and Minotaurs that spawn simultaneously must die within 5 seconds of each other."}},{"n":"Atheon, Time's Conflux","kind":"enc","goal":"Destroy nine Oracles in order across the teleports to earn Time's Vengeance, then damage Atheon. No final stand.","roles":["Teleported team (three players): picks up the Relic, destroys the Oracles in the called order, and leaves through the portal.","Outside team (three players): kills Supplicants, calls the Oracle order and opens the correct portal with the sync plate."],"steps":["Shoot the Vex cube floating over the island to start.","Kill Harpies until three players are teleported. They call out which side they went to: the jungle side is on the right, the desert side on the left.","The outside team opens the matching portal and calls the Oracle order as the Oracles spawn.","The inside team destroys them in that order. This repeats until nine Oracles are down.","The Relic holder kills Praetorians near the exit and uses the Relic's cleansing bubble to clear the blinding effect from players coming out of the portal.","When the ninth Oracle dies, everyone gets Time's Vengeance for 30 seconds: faster ability regeneration and the ability to damage Atheon."],"dps":"Stand on the stairs by the exit portal, with Ward of Dawn to the side and Well of Radiance on the stairs. A random player gets Imminent Detain, which detains them and anyone nearby; free them by shooting the detainment field. The Relic's shield does not block Atheon's attacks. The Relic holder can drop it to deal damage but must pick it back up within 10 seconds. When Time's Vengeance ends the Relic disappears: clear the remaining Supplicants and Harpies before the next teleport.","wipes":["Oracles destroyed out of order or too late wipe the whole team."],"chal":{"n":"Ensemble's Refrain","d":"Each player may only destroy one Oracle per wave."}}],"chests":["Right after Opening the Vault: inside the doorway, to the left, once the fight ends.","Before the Confluxes: follow the hidden path to a cliff and jump off facing backwards. The chest is on a ledge near a Vex plate, reached through a hole in the wall (some platforming).","Gorgons' Labyrinth: after the Templar, shoot the three Vex cubes around the maze. The chest is locked behind a door near the maze entrance.","After the Gorgons' Labyrinth: finish the jumping puzzle before Atheon. At the entryway, the chest is on a ledge above the first archway."],"loot":{"Confluxes":["Vision of Confluence","Found Verdict","Corrective Measure","Gauntlets","Class item"],"Oracles":["Praedyth's Revenge","Vision of Confluence","Found Verdict","Gauntlets","Boots"],"The Templar":["Fatebringer","Vision of Confluence","Corrective Measure","Gauntlets","Chest armor"],"The Gatekeeper":["Fatebringer","Found Verdict","Hezen Vengeance","Helmet","Boots"],"Atheon, Time's Conflux":["Praedyth's Revenge","Corrective Measure","Hezen Vengeance","Helmet","Chest armor","Vex Mythoclast (exotic)"]},"lootNote":"Challenge completions on Master reward Timelost (adept) versions: Vision of Confluence (Confluxes), Praedyth's Revenge (Oracles), Fatebringer (Templar), Hezen Vengeance (Gatekeeper), Corrective Measure (Atheon).","src":[["Shacknews: Vault of Glass raid guide","https://shacknews.com/article/124508/vault-of-glass-raid-guide-destiny-2"],["Shacknews: Vault of Glass loot table","https://shacknews.com/article/128820/vault-of-glass-loot-table-destiny-2"],["Blueberries: VoG challenges","https://www.blueberries.gg/leveling/destiny-2-vog-challenges/"],["Gfinity: VoG hidden chests","https://origin.gfinityesports.com/destiny/destiny-2-vault-of-glass-hidde-chests"]],"b":"Vault of Glass","k":["Vault of Glass"],"pl":{"1_0":0,"2_0":3,"2_1":1,"2_2":2,"3_0":4,"4_0":6,"4_1":6,"4_2":6}},{"id":"votd","n":"Vow of the Disciple","type":"Raid","players":"6","loc":"Throne World (Savathûn's), Witch Queen","rel":"The Witch Queen (March 2022)","intro":"A Hive and Scorn raid inside the Pyramid on Savathûn's Throne World. Almost every encounter is about reading the raid's symbols and shooting or depositing the right ones. Pervading Darkness builds up throughout and kills at ten stacks.","basics":["Pervading Darkness: builds over time in many areas; ten stacks kill. Different encounters give different ways to clear it.","Symbols: the raid uses a set of 26 symbols (Traveler, Pyramid, Darkness, Light, Guardian, Kill, Give, Worship, Stop and more). Agree on names for them before you start."],"enc":[{"n":"Opening and the Disciple's Bog","kind":"trav","goal":"Defeat the Projection of Savathûn at the entrance, then escort the barge through the swamp.","steps":["Defeat the Projection of Savathûn and the enemies around her to open the doors. Any damage works; Heavy weapons are quickest.","Kill Knowledge Bearer Abominations, collect the Knowledge they drop and deliver it to the barge. Knowledge grows from Heightened to Brimming to Overflowing as you collect more.","Standing near the barge removes Pervading Darkness.","The first checkpoint comes after this section."]},{"n":"Acquisition","kind":"enc","goal":"Read the symbols, record the right three, and shoot them on each of the three obelisks before they fill up.","steps":["Shoot the central crystal to open and close the room doors. Split into pairs, one pair per obelisk.","The top symbol on the reference pillar shows which side the Disciple's Compass spawns on. Kill it to reveal a second symbol, which matches a door.","Enter that room. Screeb and two Glyphkeepers spawn. Killing the Glyphkeepers reveals two symbols, and a third on the pillar (light or dark) tells you which one to record.","Repeat until three symbols are recorded, then shoot the three symbols on the obelisk within a few seconds of each other.","Do this for all three obelisks."],"wipes":["An obelisk that fills completely wipes the team (Obelisk Decimation). Correct symbols drain it; wrong symbols and Abated Adherent Scorn firing at it fill it faster."],"tips":["Unstoppable Abominations spawn, so bring Unstoppable mods. Grenade launchers with Blinding grenades help, and Supers or Heavy speed up the Glyphkeepers."],"chal":{"n":"Swift Destruction","d":"Kill all Champions within a few seconds of each other, on all rounds."}},{"n":"The Caretaker","kind":"enc","goal":"Stun the Caretaker, collect all nine symbols from the dark room and shoot them on the obelisk, then damage him on the timed plates. Three floors, then a final stand.","roles":["Two players stun the Caretaker.","Two players clear enemies.","Two players take turns collecting symbols in the dark room."],"steps":["The stunners alternate between his face and his back: face shots stun him and open his backpack, back shots close it. Destroy his homing projectiles.","Runners take turns entering the dark room, collecting any three symbols, shooting them on the obelisk, then swapping. The room has Shadow Thrall and two very tough Wizards: don't try to kill them. Pervading Darkness builds in there.","Collecting all nine symbols starts the damage phase."],"dps":"Three damage plates turn on one at a time for 10 seconds each, starting on the side the Caretaker came from. Standing on a plate gives Resonant Breakthrough; deal as much damage as you can on each. Repeat on three floors (the dark rooms get bigger and the plates farther apart). Final stand: a staircase descends to a corridor with three more plates. If the Caretaker isn't dead when the last plate turns off, the team wipes.","chal":{"n":"Base Information","d":"Runners cannot pick up more than one (1) stack of Knowledge (Glyph) on each run."}},{"n":"Platforming","kind":"trav","goal":"Cross the shifting platforms to the next encounter.","steps":["Darkness switches move the platforms. Follow the path with the wall on your right."]},{"n":"Exhibition (The Upended)","kind":"enc","goal":"Carry three artifacts through the rooms, read the symbols, shoot them on each exit doorframe, and deposit the artifacts before Terminal Resonance runs out.","steps":["Split into two groups of three, left and right; you meet again at set points.","Some symbols are only visible to a player holding an artifact.","The artifacts: the Seed removes the shield from the Disciple's Hourglass so it can be killed; the Relic (Aegis) cleanses Pervading Darkness; the Eye of Riven destroys Taken tethers with its grenade.","Terminal Resonance counts down; at zero the team wipes. Each Disciple's Hourglass killed adds 40 seconds, and so does each artifact deposited. An Hourglass spawns after each set of Glyphkeepers dies.","Curbed Resonance (30 seconds) stops you picking up a second artifact."],"tips":["In the last two rooms the Taken tether can spawn on either side, so plan the Eye of Riven route.","Bring Overload mods for the Overload Taken Hobgoblins, and roaming Supers for groups."],"chal":{"n":"Defenses Down","d":"Each player cannot kill more than one Taken Knight in total."}},{"n":"Rhulk, Disciple of the Witness","kind":"enc","goal":"Use Leeching and Emanating Force to deposit the right symbols at the obelisks, then stagger Rhulk four times and damage him.","steps":["Shoot the force field crystal. Kill the Glyphkeepers on the left and right to reveal symbols; one set is only visible to players with Leeching Force.","Leeching Force comes from shooting the central crystal (or, later, Rhulk's glaive). Standing in a darkness blast while holding it turns it into Emanating Force.","The Leeching Force holder stands on the middle plate while two players shoot the small side crystals to take it. Two players pass Leeching Force between them; two convert it to Emanating Force and deposit it at the obelisk with the called symbol (name them L1–L3 and R1–R3).","Repeat until six are deposited or the force field reaches the stairs. If nobody holds Leeching Force, kill another pair of Glyphkeepers.","Then Rhulk enters the arena. Shoot his glaive for Leeching Force, convert it, and deposit it in the corner matching the called symbol. A deposit staggers him and shows a weak point; destroying it gives another glaive. Four weak-point cycles lead to damage."],"dps":"Damage him, then go back to the starting area when he turns immune. You get three cycles before he enrages. Final stand: Rhulk keeps moving and firing darkness blasts while Pervading Darkness builds; reaching x10 before he dies wipes the team. Save one-and-done Supers for the final stand.","chal":{"n":"Looping Catalyst","d":"Do not lose Leeching Force before the damage phase."}}],"chests":["Disciple's Bog: shoot three hidden Pyramid spikes to open a building above the swamp, right of the fifth barge stop. They are under the fallen tree at the first stop, at the end of the long hall (turn left) at the second stop, and under the bridge after the third stop.","Platforming section: follow the path with the wall on your right to a room you reach by jumping between tube-shaped platforms."],"extra":{"t":"Secret Deepsight puzzle","b":["Nine hidden rooms throughout the raid are each tied to a symbol.","Matching them to the obelisk symbols spawns a reward chest with a Deepsight weapon after Rhulk."]},"loot":{"Acquisition":["Submission","Deliverance","Cataclysmic","Helmet","Chest armor","Leg armor"],"The Caretaker":["Submission","Insidious","Forbearance","Cataclysmic","Helmet","Gauntlets","Class item"],"Exhibition":["Submission","Deliverance","Chest armor","Leg armor"],"Rhulk":["Insidious","Forbearance","Lubrae's Ruin","Helmet","Gauntlets","Class item","Collective Obligation (exotic)"]},"lootNote":"Collective Obligation drops only from Rhulk.","src":[["Shacknews: Vow of the Disciple raid guide","https://shacknews.com/article/129163/vow-of-the-disciple-raid-guide-destiny-2"],["Shacknews: Vow of the Disciple loot table","https://shacknews.com/article/129267/vow-of-the-disciple-loot-table-destiny-2"],["Destinypedia: Vow of the Disciple","https://destinypedia.com/Vow_of_the_Disciple"],["Kyber's Corner: raid challenges","https://kyberscorner.com/destiny2/raid-challenges/"]],"b":"Vow of the Disciple","k":["Vow of the Disciple"],"pl":{"0_1":"top","0_2":"top","0_3":"top","1_0":1,"2_0":2,"2_1":2,"2_2":2,"3_0":4,"4_0":5,"4_1":5}},{"id":"dual","n":"Duality","type":"Dungeon","players":"3","loc":"The Derelict Leviathan (the Moon)","rel":"Season of the Haunted (May 27, 2022)","intro":"A Cabal dungeon inside Calus's derelict Leviathan, where you hop between the real world and Caiatl's nightmare by shooting a giant bell. Most of the work is collecting Standard Essence in the nightmare and depositing it on the matching plate back in reality.","basics":["Shoot the Bell of Conquest to swap between the waking realm and the nightmare realm.","Nightmare Collapsing: a countdown while you're in the nightmare. If it reaches zero the team wipes, so go back to reality in time.","Standard Bearers (Psions) drop Standard Essence. Deposit it on the plate with the same symbol: Axe, Chalice, Sun or War Beast (dogs)."],"enc":[{"n":"Navigate the Mindscape","kind":"trav","goal":"Use bell shots to move between reality and the nightmare and push forward."},{"n":"Nightmare of Gahlran, Sorrow Bearer","kind":"enc","goal":"Collect Standard Essence in the nightmare, deposit it in reality, open the side rooms and kill the Visions of Gahlran to reach the real boss.","steps":["Kill the Bellkeepers to summon the Bell of Conquest, then shoot it to enter the nightmare.","In the nightmare, kill the Standard Bearers (Psions in the two corner rooms) and pick up their Standard Essence.","Go back to reality and deposit it on the matching plate (Chalice, Sun, Dogs or Axes).","Depositing spawns Colossi in the side rooms. Shoot the bell from those rooms to enter the nightmare's closed rooms.","Kill the Visions of Gahlran to open the doors to the boss, then damage him."],"dps":"A 60-second countdown starts with damage. Shoot the bell to return to reality before it ends.","wipes":["The damage countdown reaching zero.","Nightmare Collapsing reaching zero."],"tips":["On Master, Bellkeepers have Void shields and Unstoppable Incendiors appear in the side rooms."]},{"n":"Navigate the Crypt","kind":"trav","goal":"Climb the tombs over the chasm, then turn the four statues to face inward.","steps":["Pull the lever across the chasm to extend the tombs and climb them.","Four statues must all face inward; the only hint is \"Find the Way\".","Each statue's button in the nightmare turns the real statue 90 degrees counter-clockwise. When all four face inward, the middle floor opens."]},{"n":"Open the Vault","kind":"enc","goal":"Deposit six Standard Essences to kill the three Nightmares guarding the vault.","steps":["Match the symbols on the floor to the symbol-marked blocks to find each Standard Bearer.","Every two essences deposited makes the current Nightmare vulnerable. Kill all three (Emonut, Ka'hok and Uroa).","Carrying two essences at once saves trips but isn't required.","After the third Nightmare, the floor opens to the rewards."]},{"n":"Navigate the Vault","kind":"trav","goal":"Use more bell shots and cross the chasm to the Dark Shrine."},{"n":"Nightmare of Caiatl","kind":"enc","goal":"Deposit four Standard Essences, ring the big bell, then stun Caiatl at each bell she runs to.","steps":["Kill the Bellbearers to activate the bells.","Match the two symbols near the chains to the balconies.","In the nightmare, kill the Psions on the matching balconies to spawn Standard Essence. Each Psion killed adds time to your Nightmare Collapsing timer.","Deposit four essences in total. Then shoot the glowing purple gem to ring the large bell and start damage.","Caiatl runs to a bell. Shoot that bell to stun her for 10 seconds and stand near it for the Waking Resonance damage buff.","Damage ends after all three bells, or early if she reaches a bell."],"dps":"Three 10-second stuns. Stand close to the bell to keep Waking Resonance.","tips":["On Master, Barrier Colossi appear in the nightmare; bring anti-barrier (Arbalest works)."]}],"chests":["Navigate the Crypt (after the statue puzzle): in an alcove behind a slightly open door in the normal realm.","Navigate the Vault: in a cramped passage directly below the large shrouded object in the central room."],"extra":{"t":"Heartshadow","b":["Heartshadow, an exotic Void sword, is a random drop from the dungeon's final chest.","Its catalyst unlocks after you own it: defeat the three Failed Assassins Ka'nok, Regor and Hou'dal, hidden across the dungeon."]},"lootAll":["Fixed Odds","Lingering Dread","New Purpose","Stormchaser","The Epicurean","Unforgiven","Deep Explorer armor","Heartshadow (exotic sword)"],"lootNote":"The in-app list loads Bungie's own collection data, so it stays correct if the pool changes.","src":[["Shacknews: Duality dungeon guide","https://www.shacknews.com/article/130585/destiny-2-duality-dungeon-guide"],["Destinypedia: Duality","https://www.destinypedia.com/Duality_(dungeon)"]],"b":"Duality","k":["Duality"],"pl":{"1_0":1,"2_0":3,"3_0":5}},{"id":"eq","n":"Equilibrium","type":"Dungeon","players":"3","loc":"Launched from the Portal (Lawless Frontier)","rel":"Destiny 2: Renegades (December 2025)","intro":"The Renegades dungeon: a boarding action against Cabal Imperium ships hunting Dredgen Sere. The key resource is Shadow energy: gather it to rank up from Shadow Novice to Apprentice to Master, which swaps your grenade for a Shadow attack that breaks Darkness shields, devices and panels.","basics":["Gathering Shadow pools build your Shadow rank: Shadow Novice, then Shadow Apprentice, then Shadow Master. With it, your grenade becomes a special Shadow attack.","Use the Shadow attack on Darkness shields, Darkness devices and Darkness panels.","It came with Destiny 2: Renegades (now part of Destiny 2: The Collection). Launch it from the Lawless Frontier in the Portal."],"enc":[{"n":"Temple Grounds","kind":"trav","goal":"Clear the starting area and reach the arena with the docked jump ship."},{"n":"Harvester (Barant Imperium Forces)","kind":"enc","goal":"Strip the shields from six Nameless Apprentices and kill them, plus the Behemoths, to spawn the chest.","steps":["Interact with the docked ship to start the first wave.","Three Nameless Apprentices spawn with immunity shields. Lead one to the Cabal device near the red barrier and extend an Arc pylon from the device to charge it.","Ride Sparrows through the tunnels and collect Gathering Shadow to become a Shadow Novice. If you don't, Creeping Shadows kills you in the tunnels.","When an Apprentice summons Darkness energy, the Shadow player uses the special grenade to break its shield.","Each Apprentice killed calls in a Cabal drop pod with enemies and a Behemoth walker, and leaves Gathering Shadow pools.","Kill six Apprentices and the remaining Behemoths. Board the Harvester jump ship to continue."],"wipes":["Creeping Shadows in the tunnels without Shadow energy.","A drop pod landing on you."]},{"n":"Search for Imperial Intelligence","kind":"trav","goal":"Work through the hangar, cargo bay and maintenance shaft to Harrow.","steps":["Jump through the red-lit hangar, shoot the grate to drop down and wait for the whole team so the door opens.","Shoot fuses to open the cargo bay gap and clear both barriers.","The maintenance shaft is trapped: it explodes when shot.","Don't shoot the window. You'll be pulled out into space."]},{"n":"Harrow, Dredgen Apprentice","kind":"enc","goal":"Rank up to Shadow Apprentice, power the Darkness devices, strip Harrow's shields and damage him.","steps":["Shoot the fuse in the rally flag room and drop into the arena. Harrow fights with two Praxic Blades.","Kill enemies and Lackeys (they drop Darkness energy) to reach Shadow Novice, then Shadow Apprentice.","Use the special grenade on the Darkness devices and panels; there are three per room, and green lights show which are done.","Remove Harrow's shields by baiting him into the hole (using the red bay doors and fuses) or by hitting the pylons in the room corners.","Pylons and fuses don't come back, so plan for about three damage phases.","At his health split his shields reset and he runs. His shields falter at the far end of the hallway; finish him there."],"dps":"About 30 seconds per phase before he's immune again."},{"n":"Board the Malphas Contemptus","kind":"trav","goal":"Get onto the command ship and through it to Sere.","steps":["Use Shadow Apprentice on a Darkness panel to reveal a switch, then flip the switch by Harrow's chest to open the bay door.","Jump onto the ship's edge, use the red-lit switches to open the blast doors and go down along the underside.","Use the central console in the hangar to move the platforms, then enter the ship.","Get past the Behemoths into the tank elevator tunnel and shoot the correct grate (three are dead ends).","Reach the pipe with platform jumps or movement abilities, building Shadow Apprentice on the way. Kill the two Praetorians."]},{"n":"Dredgen Sere","kind":"enc","goal":"Destroy the five Taken orbs in both the real arena and the Taken plane, compel the Blistered Shadows, then damage Sere.","steps":["Approach or shoot Sere or his kneeling Apprentices to start. Stay away from his opening slam.","A 45-second Lure of the Dark timer starts. Build to Shadow Master and kill Nameless Apprentices to destroy the Taken orbs in the centre.","You're pulled into the Taken arena with five Blistered Shadows. Compel each one by interacting with it while you hold Shadow Master. Killing two lowers the Lure of the Dark stacks you need and increases your damage to Sere.","Hit the Darkness-protected panels to make platforms up to the fifth Blistered Shadow.","Back in the real arena with full Lure stacks, kill Nameless Apprentices to destroy the remaining orbs. Break the last one near Sere so you don't waste damage time.","If Sere survives, stay out of the Arc energy in the centre and shut off the Arc pylons by hitting the nearby Darkness panels with the Shadow grenade. Repeat."],"wipes":["Sere's opening slam if you're too close.","Standing in the central Arc energy after damage."]}],"chests":["Two hidden chests. They drop dungeon armor and weapons."],"extra":{"t":"Heirloom (exotic bow)","b":["Heirloom, a Solar exotic combat bow, is a random drop from Dredgen Sere.","Completing the dungeon's feat triumphs (Phase Race, Encounter Challenges, Cutthroat Combat, Token Enabled, Battalions and others) raises its drop chance.","Its catalyst comes from The Way Between questline, started by talking to Aunor."]},"loot":{"Harvester":["Sage Protector armor","Voltaic Shade","Zealous Ideal","Bitter End"],"Harrow":["Sage Protector armor","Voltaic Shade","Conspiracy Honed","Bitter End"],"Dredgen Sere":["Sage Protector armor","High Tyrant","Zealous Ideal","Voltaic Shade","Bitter End","Sullen Claw","Conspiracy Honed","Heirloom (exotic bow)"]},"lootNote":"Per-encounter drops as listed by Kyber's Corner. The in-app list loads Bungie's own collection data.","src":[["Shacknews: Equilibrium dungeon guide","https://www.shacknews.com/article/147168/how-to-complete-the-equilibrium-dungeon-in-destiny-2"],["Kyber's Corner: Equilibrium","https://kyberscorner.com/destiny-2-equilibrium-dungeon/"]],"b":"Equilibrium","k":["Equilibrium"],"pl":{"0_2":"top","1_0":4,"1_1":3,"1_2":1,"1_3":1,"1_4":1,"1_5":2,"1_6":2,"1_7":2,"1_8":2,"1_9":3,"1_10":4,"2_0":5,"2_1":5,"2_2":5,"2_3":5,"2_4":5,"2_5":5,"2_6":5,"2_7":5}},{"id":"gotd","n":"Ghosts of the Deep","type":"Dungeon","players":"3","loc":"New Pacific Arcology (Titan)","rel":"Season of the Deep (May 26, 2023)","intro":"A Lucent Hive dungeon under Titan's methane sea. Kill Lightbearers for their Vestige of Light, carry it to the right statue or rune, and crush Hive Ghosts so the Lucent Brood stay dead. Much of it is fought underwater.","basics":["Killing a Lightbearer gives you a Vestige of Light. Take it to the statue or rune the encounter asks for; the wrong one backlashes and kills you.","A Veilweaver Wizard grants Deepsight, which reveals the runes you need to match.","Lucent Hive bring back their dead with Ghosts. Crush the Ghost after a kill.","Underwater, oxygen bubbles are shared by the team and Ecthar's attacks drain your pressure gauge rather than your health."],"enc":[{"n":"Hive Ritual","kind":"enc","goal":"Charge the four thrall statues with Vestiges of Light.","steps":["Each of four cycles: kill a Soulfire Binder Ogre, follow the trail to a rune and note its symbol, clear the Hive squad there and kill the Lightbearer for the Vestige.","Kill the Veilweaver Wizard to get Deepsight, which reveals the runes on the statues. Keep one player at the ritual site for it.","Take the Vestige back and dunk it in the statue that matches the rune where you picked it up.","A jumping section follows once all four statues are charged."],"wipes":["Dunking a Vestige in the wrong statue kills you."]},{"n":"The Descent","kind":"trav","goal":"Sink down the structure and through the underwater rooms.","steps":["Turbines push you up into rooms with air. Stay near the shared oxygen bubbles.","Leave the acolytes near Ecthar's entrance alone until the whole team is ready: killing them starts the fight.","The first hidden chest is at the end of this section (see chests)."]},{"n":"Ecthar, the Shield of Savathûn","kind":"enc","goal":"Charge three statues with Vestiges, then stand where the Wellkeeper Knight died to break Ecthar's shield and damage him.","steps":["Killing the acolytes near the entrance brings out a Keeper of the Deep. Its drop shows three symbols.","Dive into the water and touch the matching symbols underwater. Each spawns a Lightbearer above water; take its Vestige to any uncharged statue.","When all three are charged, Ecthar appears with a Wellkeeper Knight. Kill the Knight quickly and stand where it died to bring Ecthar's shield down.","Damage him. The damage timer starts when he appears, so be quick.","If he dies, crush his Ghost. If you don't, he comes back with some health."],"wipes":["Wrong statue: the backlash kills the dunker.","Running out of pressure underwater."]},{"n":"The Chasm","kind":"trav","goal":"Cross the chasm of Lucent Hive, Shriekers and Wizards to the final room.","steps":["The second hidden chest is on the structure the Ogre spawns from (see chests)."]},{"n":"Šimmumah ur-Nokru","kind":"enc","goal":"Imbue the three orbs over Oryx's body, then break Šimmumah's shield and damage her.","steps":["Crush the unclaimed Ghost to start. Deepsight shows three orbs over parts of Oryx's body.","Vorlog, a Knight, chases players and comes back when killed. Killing him under an orb draws Šimmumah to that spot.","From ground level, line up the floating ring with the Taken symbol to reveal a rune. Do this for each of the three orbs.","Lightbearer Adherents in the methane pockets give Vestiges. Place each on the matching rune.","When all three orbs are imbued, shoot down Šimmumah's shield and start damage. Crush her Ghost to finish the dungeon."],"dps":"Her damage phase opens once all three orbs are imbued and her shield is down."}],"chests":["Before Ecthar: after the long dive, leave through the cracked window onto the sea floor and jump off the big cliff. Part way down, a ledge pulls you out of the water right beside the chest. If you miss it, clear the enemies on land and climb up.","Before the final boss: crossing the chasm, a large group spawns with an Ogre. Kill the Ogre, climb onto the structure it came out of; the chest is in the middle of the roof."],"extra":{"t":"The Navigator","b":["The Navigator, an exotic Strand trace rifle, is a random drop from the final boss.","Its catalyst comes from hunting Thul-Ar, Acolyte of Nokris, across three piles of Ghosts in the dungeon."]},"lootAll":["The Navigator (exotic trace rifle)"],"lootNote":"Ghosts of the Deep's legendary pool has changed since launch. The in-app list loads Bungie's own collection data.","src":[["Destinypedia: Ghosts of the Deep","https://www.destinypedia.com/Ghosts_of_the_Deep"],["Prima Games: Ghosts of the Deep secret chests","https://primagames.com/tips/secret-chest-locations-in-destiny-2-ghosts-of-the-deep"]],"b":"Ghosts of the Deep","k":["Ghosts of the Deep"],"pl":{"1_0":0,"1_1":0,"1_2":0,"1_3":0,"2_0":2,"2_1":2,"2_2":2,"3_0":4,"3_1":4}},{"id":"goa","n":"Grasp of Avarice","type":"Dungeon","players":"3","loc":"The Cosmodrome (Earth)","rel":"30th Anniversary Pack (December 2021)","intro":"A Fallen pirate dungeon built around the original Loot Cave. Kill enemies, grab the engrams they drop, and dump them into the crystal before the greed debuff kills you. It came with the 30th Anniversary Pack, which is now part of Destiny 2: The Collection.","basics":["Picking up engrams gives you Burdened by Riches. It stacks, and a 30-second timer kills you if it runs out; deposit your stacks at the crystal to clear it.","At 10 stacks your Super refreshes.","Scorch Cannons (dropped by a Scorch Vandal, the Gunner of Avarokk) power generators and open doors throughout the dungeon."],"enc":[{"n":"Skywatch: Loot Cave Crystal","kind":"enc","goal":"Feed the crystal in the cave until it is sated.","steps":["Kill enemies and collect the engrams they drop to build Burdened by Riches.","Stand next to the crystal in the cave to deposit. Repeat until it is full.","The section ends when \"The remains are quieted\" appears."]},{"n":"Rusted Gangplank: Trap Puzzle","kind":"trav","goal":"Work through the trap rooms and open the way to Phry'zhia.","steps":["Take the left door, jump the pressure plate trap and pull the lever by the computer.","Cross the trapdoor platform, go under its right side and pull the lever at the terminal.","Go back and step on the pressure plate at the back right of the six holes to open a grate. Climb through.","Pull the lever by the next terminal to bring out the catwalk over the flooded chasm.","In the flip-door rooms, use the switch in each room to move on; the lever at the end opens the main gate.","In the round room, kill the Scorch Vandal (Gunner of Avarokk) for the Scorch Cannon and shoot the generators in this order: Door 03, Door 04, Door 01, Door 02.","Climb the containers to the flooded room and jump across to Phry'zhia."]},{"n":"Phry'zhia the Insatiable","kind":"enc","goal":"Open the garages with the Scorch Cannon, collect engrams inside and deposit them at the crystal to break the shield.","steps":["Shoot a generator with the Scorch Cannon to open a garage door, clear the enemies inside and grab the engrams.","Deposit at the crystal. Repeat until \"Phry'zhia the Insatiable has succumbed to temptation\" appears.","Damage Phry'zhia. The loot chest is in the middle of the arena after the kill."],"tips":["On Master, Anti-Barrier Knights spawn in the garages. Deposit after clearing each garage."]},{"n":"Shroud: Sparrows and Mines","kind":"trav","goal":"Race down the track and defuse mines A, B, C and D before the fuse runs out.","steps":["Drive past the timer buttons to extend the fuse.","A: right side, under ship wreckage.","B: inside the ship, before the hexagonal centre, on the right.","C: before the Spider tank drop-off, behind wreckage in the middle of the route.","D: right side, at the top of a ramp before the gravity cannons."]},{"n":"Sunken Lair: Destroy the Shield","kind":"enc","goal":"Destroy the four nodes on the central structure with the big cannon to drop its shield.","steps":["Use Scorch Cannon shots on generators to aim the gravity cannons and hop between platforms.","Kill the Abundance Monitor Servitors, deposit engrams at the central crystal to lower their shields, then push the shell onto a cannon platform.","Fire the cannon at the central structure to destroy one node. Destroy all four to drop the main shield.","Rewards are up the stairs from the cannon on the middle platform."],"tips":["On Master, Overload Captains spawn at each point. Kill them first."]},{"n":"Captain Avarokk, the Covetous","kind":"enc","goal":"Fire the Scorch Cannon into a generator, collect the engrams from the pods and deposit them to break Avarokk's shield.","steps":["Kill the Scorch Vandal and fire the cannon into one of the three generators.","Collect the engrams that fall from the pods and deposit them at the central crystal.","When \"Avarokk the Covetous has succumbed to temptation\" appears, you have a 30-second damage phase.","When he \"resists temptation once more\", start the next cycle."],"dps":"30 seconds per phase.","tips":["On Master, Anti-Barrier Servitors spawn during collection. Group up behind the pod."],"wipes":["Burdened by Riches timer running out kills the holder."]}],"chests":["Cave: walk across the crystals until you see a metal grate above; the chest hangs off its side. Damage the Vandal across the cavern on the right until it drops a Cursed Engram, then open the chest.","After the rolling barrel trap: a Vandal in the next room drops the engram. In the first boss room, go right along the concrete wall and drop into the indent in the wall.","Sunken Lair: after the shield is down, don't jump to the boss. The chest is on the structure on the middle island; a Vandal on the island with the waterfalls drops the engram."],"extra":{"t":"Gjallarhorn","b":["Gjallarhorn's quest needs a Grasp of Avarice clear with the quest active.","Its catalyst, More Wolves, unlocks after 400 kills with the weapon."]},"lootAll":["Matador 64","Hero of Ages","1000 Yard Stare","Eyasluna","Dungeon armor set (Artifice armor on Master)","Gjallarhorn (exotic, via quest)"],"lootNote":"The in-app list loads Bungie's own collection data, so it stays correct if the pool changes.","src":[["Shacknews: Grasp of Avarice guide","https://shacknews.com/article/128012/grasp-of-avarice-dungeon-guide-destiny-2"],["Kyber's Corner: Grasp of Avarice","https://kyberscorner.com/destiny2/grasp-of-avarice/"],["Grindout: Grasp of Avarice secret chests","https://grindout.com/destiny-2/guides/grasp-of-avarice"]],"b":"Grasp of Avarice","k":["Grasp of Avarice"],"pl":{"1_0":3,"1_1":3,"1_2":3,"1_3":3,"2_0":1,"2_1":1,"2_2":1,"3_0":1,"3_1":1,"3_2":1,"4_0":5,"4_1":0,"4_2":5,"4_3":0,"4_4":2}},{"id":"poh","n":"Pit of Heresy","type":"Dungeon","players":"3","loc":"Beneath the Scarlet Keep, Sorrow's Harbor (the Moon)","rel":"Shadowkeep (October 29, 2019)","intro":"A Hive dungeon under the Scarlet Keep. Nearly every room is solved the same way: pick up a Hive sword or a Knight's orb, use it on the right target, and keep moving before the Hive curse gets out of hand.","basics":["Hive Relic swords drop from Knights. Their light attack, ranged heavy attack and guard each have a use against specific minibosses.","Orbs from Heretical Knights are carried to doors or runes and dunked to extinguish them.","Gate Lord's Eye and the artifact have changed over time, so loadout tips from 2019 guides may no longer apply."],"enc":[{"n":"Necropolis","kind":"enc","goal":"Find the three towers that match the symbols on the chain and kill the miniboss in each with a Hive sword.","steps":["Note the symbols on the chain, then find the three matching giant holograms outside.","Each room holds a Broken Blade miniboss. Pick up a Relic sword dropped by a Knight to damage it.","Each miniboss needs a specific sword move: Knight → light attack, Wizard → ranged heavy attack, Shrieker → guard.","Kill all three and the chains break. Follow the green beam of light out."]},{"n":"Tunnels of Despair","kind":"trav","goal":"Use Knight orbs to open the three doors while avoiding the Ogres.","steps":["Shoot the webbing to get into the caves.","Kill Heretical Knights, take their orbs and dunk them in the doors to extinguish them.","Three Harrowing Pariah Ogres patrol the tunnels. They can't be killed and hit very hard: sneak around them or have one player lead them away."]},{"n":"Chamber of Suffering","kind":"enc","goal":"Keep the Totem player alive while the others dunk six Knight orbs to remove the runes.","steps":["One player stands on the plate under the Annihilator Totem. If no one is on it, the Totem wipes the team. Well of Radiance helps the plate player.","The others kill the Heretical Knights and dunk their orbs; each orb removes one rune from the pillars. Six orbs open the door.","Kill Knights that spawn up high first: they shell the plate.","Speed matters. The Curse of Suffering debuff stacks over time and makes enemies hit much harder; at five stacks most enemies can almost one-shot you. Dunking an orb lowers your own stacks."],"wipes":["No one on the plate under the Annihilator Totem.","Curse of Suffering stacks getting too high."]},{"n":"The Harrow","kind":"trav","goal":"Find the three symbols in the maze and kill the Malevolent Ritualist Wizard at each.","steps":["Remember the three symbols at the entrance, then find them inside the maze.","Kill the Malevolent Ritualist (a Wizard) near each symbol to break its lock. Wizards hit hard and there are traps that drop you; move carefully.","Break all three locks to finish."]},{"n":"Zulmak, Instrument of Torment","kind":"enc","goal":"Use Hive swords to kill the three tower minibosses, dunk their orbs in the centre and damage Zulmak from inside the centre circle.","steps":["Kill the Knights around the centre and take their Relic swords.","Kill the three tower minibosses with the matching move: Knight → light attack, Wizard → ranged heavy attack, Shrieker → guard.","Carry the three orbs to the centre and extinguish the pedestal. This starts damage and puts a green aura around the crystal.","You can only damage Zulmak while standing in the centre.","When he kneels to charge the crystal, get out of the centre. The blast kills anyone still inside.","His ranged attack sends a line of fire that leaves a burning circle. Step out of it."],"dps":"Stand in the centre circle and leave the moment he kneels.","wipes":["Standing in the centre when Zulmak's charge finishes kills you."]}],"extra":{"t":"Xenophage","b":["Xenophage, a Solar exotic machine gun, comes from an exotic quest that runs through this dungeon; its steps are puzzles spread across the dungeon's rooms."]},"lootAll":["Adamantite","Refusal of the Call","Psychopomp","Eyes Unveiled","Apostate's Blade Suit armor","Xenophage (exotic, via quest)"],"lootNote":"Loot as listed by Destinypedia since Monument of Triumph. The in-app list loads Bungie's own collection data.","src":[["Shacknews: Pit of Heresy guide","https://shacknews.com/article/114869/pit-of-heresy-guide-destiny-2"],["Destinypedia: Pit of Heresy","https://destinypedia.com/Pit_of_Heresy"]],"b":"Pit of Heresy","k":["Pit of Heresy"],"pl":{"1_0":1,"2_0":3}},{"id":"proph","n":"Prophecy","type":"Dungeon","players":"3","loc":"The IX Realms (Unknown Space)","rel":"Season of Arrivals (June 9, 2020)","intro":"A strange trip into the Nine's realm, guided by Toland. The whole dungeon runs on one rule: kill Knight Echoes in light or shadow to collect Light or Dark Motes, then spend five of the same kind on the matching plate.","basics":["Kill a Knight Echo while it stands in light and it drops Light Motes; kill it in shadow and it drops Dark Motes.","Five motes of the same type make a charge. Use it on a smoke plate of the same colour to cleanse it.","Motes last 30 seconds and each pickup resets the timer. Picking up a mote of the other type wipes your progress.","There is no exotic tied to Prophecy."],"enc":[{"n":"Entrance (Heaven/Hell)","kind":"trav","goal":"Cleanse the plates section by section down the hallway.","steps":["There's no timer here, so this is a good place to learn the mote rules.","Kill Knight Echoes in light or shadow, collect five matching motes and cleanse each plate to open the next section."]},{"n":"Phalanx Echo","kind":"enc","goal":"Cleanse all four plates to make the Phalanx Echo vulnerable, then damage it.","steps":["Agree on one mote type at a time so the team doesn't cross-contaminate.","Cleanse all four plates. The boss becomes damageable.","When it turns immune again, go back to cleansing plates and repeat.","After the kill, stand together on the sandy plate in the centre to move on."]},{"n":"Wasteland","kind":"trav","goal":"Cross the expanse and find the Hexahedron.","steps":["Clear the Taken and the Taken Blights. Enter the large stone building with the narrow entrance."]},{"n":"The Hexahedron","kind":"enc","goal":"Follow Toland's orb through six flips of the cube.","steps":["Cleanse the plate directly under Toland's orb.","If the orb is on the roof, cleanse the plate that matches the unlit side of the cube.","Hobgoblins respawn about every 60 seconds; each one you kill spawns a Knight Echo, your mote source.","If a flip goes wrong, collect the right motes again to correct it.","The last flip needs you to kill two Taken Centurions. Leave through the narrow gap in the wall."]},{"n":"Wasteland: Follow the Kell Echo","kind":"trav","goal":"Follow the Kell Echo to the far side of the Wasteland."},{"n":"Singularity","kind":"trav","goal":"Ride or run down the ribbons and diamonds to the giant diamond at the bottom.","steps":["You can use your Sparrow for most of it.","There is a weekly secret chest in a hole just before the final diamond (see chests)."]},{"n":"Kell Echo","kind":"enc","goal":"Cleanse the three plates, then chase the Kell Echo down the hallway and damage it on the end platform.","steps":["Walk up to Toland's wisp to start. Three Kell Echoes appear.","At each plate, kill the two Knight Echoes for motes, cleanse the plate and kill the Ogre that spawns. Clear the room and stand in the centre to be taken to the boss.","Chase the Kell Echo down the long hallway, killing Hobgoblins and dodging its attacks. Damage it as it flees.","It stops on the end platform for about 20 seconds. This is the main damage window.","When it turns immune, stand in the sand triangle to return to the main room and repeat."],"dps":"The ~20 seconds on the end platform. Get there fast and save heavy for it.","wipes":["Dark Entropy stacks from the Kell Echo's area attack; at 10 stacks you die. Stay out of it.","Its Darkness Bolt teleports you back to the start of the hallway and can hit through cover."]}],"chests":["Singularity: in a hole and gap just before the final diamond on the way down. Opens once per week."],"lootAll":["Judgment","Darkest Before","A Sudden Death","Prosecutor","Adjudicator","Relentless","Flowing / Crushing / Channeling armor"],"lootNote":"Every encounter can drop from the pool. The in-app list loads Bungie's own collection data, so it stays correct if the pool changes.","src":[["Shacknews: Prophecy dungeon guide","https://shacknews.com/article/118838/prophecy-dungeon-guide-destiny-2"],["Destinypedia: Prophecy","https://destinypedia.com/Prophecy"]],"b":"Prophecy","k":["Prophecy"],"pl":{"1_0":2,"1_1":0,"1_2":0,"1_3":3,"1_4":6}},{"id":"st","n":"The Shattered Throne","type":"Dungeon","players":"3","loc":"The Dreaming City (Mara Sov's throne world, reached through the Confluence)","rel":"Forsaken: Black Armory era (September 2018)","intro":"Destiny's first dungeon: a three-player run through Mara Sov's corrupted throne world. It is a long climb of traversal, add-clearing and two bosses, and it is also where the Wish-Ender exotic bow quest finishes.","basics":["You can launch it from the Director. Originally you entered through the Confluence: a hidden portal in the Dreaming City leads to a large Taken gateway guarded by a Techeun.","Restricted respawns: if you die, you wait for a long revive timer instead of coming straight back, and if the whole team dies the area resets.","Long-range weapons help everywhere: Taken Hobgoblins snipe from above, and Ogres can knock you off narrow beams."],"enc":[{"n":"Erebus: Search for Safe Passage","kind":"trav","goal":"Follow the symbols through the city and clear each marked building.","steps":["Cross the broken bridge and kill the Taken Acolytes and the Labyrinth Architect (a Taken Knight miniboss). The Acolytes keep creating Acolyte's Eyes until they die.","Clearing an area shows a symbol. Go to the building that carries the same symbol; you'll find another Labyrinth Architect with a dozen or so enemies.","Repeat until the symbol sends you back to the starting building. Clear the final Acolytes and the last Labyrinth Architect (a Taken Captain) and drop down the hole that opens."]},{"n":"Asterion, Set Apart","kind":"trav","goal":"Drop down after the checkpoint and kill the snipers and Asterion, Set Apart."},{"n":"The Descent: Journey to the Spire","kind":"trav","goal":"Cross the long hallway and the room of beams.","steps":["In the hallway, Hobgoblins snipe from the sides while Phalanxes and Knights push you. Knight fire hits hard; take them one at a time.","Turn left into the wide room and work your way across the beams to the far left. Kill each Ogre from range before stepping out: their eye blasts knock you off, and the fall is lethal."]},{"n":"The Descent: Press Onward (Thrall hall)","kind":"trav","goal":"Reach the end of the hall.","steps":["Past the barrier you can't sprint or double jump, and Shadow Thrall respawn endlessly.","Keep moving: stand on ledges, stairs and boxes where Thrall can't swarm you, and don't stop to fight the whole wave. A Warlock Healing Rift helps.","Drop off the edge at the far end."]},{"n":"The Descent: Cross the Chasm","kind":"trav","goal":"Get past the rock face and kill the Phalanxes on the other side.","steps":["Either hug the outside ledge (watch for Taken blights that push you off) or go through the doorway and climb inside the cliff. Both meet on the far side.","Fight up the stairs through a big group of Phalanxes to reach Vorgeth."]},{"n":"Vorgeth, the Boundless Hunger","kind":"enc","goal":"Kill the four Keepers of Petitions, take their Marks to a brazier and damage Vorgeth while his shield is down.","steps":["Clear the normal adds first. Each Keeper of Petitions (a Taken Wizard) comes with Taken snipers and Goblins.","Killing a Keeper drops Petitioner's Mark. Every pickup resets its 45-second timer; if it runs out, you die. Dying removes all your Marks and the Keepers have to be killed again.","The fourth Mark turns into Petitioner's Burden. Take it to one of the flames around Vorgeth to put it out. That removes his shield.","Safe trick: bring all four Keepers to very low health first, then kill them quickly one after another.","While he is shielded, Vorgeth's eye blasts hit hard and knock you back. In the damage phase he fires homing Axion Darts; shoot them down.","When damage ends, the Keepers and adds come back. Repeat until he dies."],"dps":"Short window. Spike-grenade launchers and burst heavies do well; Well of Radiance or Ward of Dawn adds safety in a group.","wipes":["Petitioner's Mark or Burden timer reaching zero kills the player holding it.","A full team death resets the fight (restricted respawns)."]},{"n":"Eleusinia: Press Onward / Ascend","kind":"trav","goal":"Go down past the statue, ride the lift, then climb the spire.","steps":["Walk through the central door past the statue, drop down the platforms and kill the Wizards around the lift.","At Ascend you can take the stairs and jump straight to the end, or turn right for the jumping section: hug the wall, time your moves around the portals that push you, and ride the lifts to the top."]},{"n":"Dûl Incaru, the Eternal Return","kind":"enc","goal":"Kill her three Knights to collect Finite Thought, then damage Dûl Incaru and cleanse at the middle before the buff kills you.","steps":["Two groups of Taken Psions spawn on the side ledges and multiply if left alone. Kill them fast; a tether or Dawnblade super helps.","Kill the three Hive Knights. Each drops a buff (Finite Thought) that lets you damage Dûl Incaru; picking up more of them increases your damage.","Finite Thought has a timer (about 45 seconds). Cleanse it at the brazier in the middle of the room before it runs out, or it kills you.","Dûl Incaru summons a crystal that makes the Knights immune. Breaking it removes their shield and brings back any Knights you killed, so you can collect the buff again.","Repeat: Psions, Knights, damage, cleanse. Use the back balcony and the pillars for cover."],"dps":"Kill all three Knights close together so everyone has the full buff, then burn her.","wipes":["Finite Thought expiring kills the holder.","A full team death restarts the encounter."]}],"extra":{"t":"Wish-Ender exotic bow","b":["Wish-Ender comes from an exotic quest that finishes in this dungeon. Bungie has changed the quest's start over the years; check the Dreaming City for the current version.","The quest gives you three Dreaming Tokens. Each one summons a hidden boss in the dungeon when you place a charged orb on the statue that is missing one.","Querim, The Waking: in the opening city, take the glowing orb from the near-western rooftops to the statue without an orb on the central rooftops. Kill the yellow-bar enemies and then Querim.","Eriviks, The Waking: in the beam room, take the orb behind the pillar to the right of the entrance across to the statue on the far wall. Then take the orb on the right at the start of the Thrall hall to the end, drop down, and place it in the statue on the right. Kill Eriviks behind the doors that open.","Xavoth, The Awakening: during Vorgeth, after a Petitioner's Burden, kill the small invisible Taken Minotaur, take its orb to the empty statue on the wall, and kill Xavoth.","After Vorgeth dies, interact with the statue of Sjur Eido in the next room to receive Wish-Ender, then go back to Petra Venj.","The Wish-Ender catalyst also drops from this dungeon."]},"lootAll":["Fractethyst","Canis Major","Chrysura Melo","Vulpecula","Techeun's Regalia armor","Wish-Ender (exotic bow, via quest)"],"lootNote":"Every encounter can drop any item from the pool. The in-app list loads Bungie's own collection data, so it stays correct if the pool changes.","src":[["Destinypedia: The Shattered Throne walkthrough","https://www.destinypedia.com/The_Shattered_Throne/Walkthrough"],["Shacknews: The Shattered Throne dungeon guide","https://shacknews.com/article/107607/shattered-throne-dungeon-guide-destiny-2"],["Blueberries: Shattered Throne loot table","https://www.blueberries.gg/weapons/shattered-throne-loot-table/"],["Blueberries: Wish-Ender quest","https://www.blueberries.gg/leveling/hunters-remembrance-quest/"]],"b":"Shattered Throne","k":["Shattered Throne"],"pl":{"1_0":0,"2_0":2,"3_0":5,"4_0":"skip","5_0":7}},{"id":"sotw","n":"Spire of the Watcher","type":"Dungeon","players":"3","loc":"The Ares Spire (Mars)","rel":"Season of the Seraph (December 9, 2022)","intro":"A Vex dungeon up and down a Rasputin-era spire on Mars. Every room is an Arc circuit: grab the Arctrician buff from a Minotaur and shoot the nodes along the cables before the buff or the circuit times out.","basics":["Conduit Minotaurs leave a pool when they die. Stand in it for Arctrician (30 seconds). While you have it, shooting an Arc node activates it, and each node adds a few seconds.","Yellow circuits must be done in order from the start of the cable to the end. A node hit out of order switches off after a couple of seconds.","Red circuits can be done in any order, but all nodes must be activated within a short window or they reset."],"enc":[{"n":"Reestablish Power","kind":"enc","goal":"Complete four yellow circuits to open the outpost door.","steps":["Kill a Conduit Minotaur, stand in its pool and follow the cables from the generator, shooting each node in order.","Finishing a circuit spawns Supplicants. Repeat until all four are done."]},{"n":"Begin the Ascent","kind":"trav","goal":"Climb the jumping section past Harpies, Hobgoblins and Incarcerator Hydras.","steps":["The first hidden chest is in this section (see chests)."]},{"n":"Ascend the Spire","kind":"enc","goal":"Complete two circuits per level to power the gravity lift, all the way to the top.","steps":["Same loop: Minotaur pool, Arctrician, nodes in order. Killing Hydras spawns Supplicants.","Each powered set sends you up the lift to the next level, ending at the reward chest."]},{"n":"Akelous, the Siren's Current","kind":"enc","goal":"Power the four fuel rods, shoot out Akelous's eyes and then damage its core.","steps":["Destroy the Minotaur Akelous is holding to start.","Run circuits from the centre outward to the four fuel rods at the ends of the boardwalks.","When all four are lit, Akelous moves to one and reveals its red eyes. Destroy them first.","It then backs off and drops its armour, exposing the core. Damage it.","At the end of the phase it lets out a blast that can knock you back or off the edge. Stay away from the edges.","If it survives, repeat the circuits. A loot chest appears in the arena after the kill."],"dps":"You can take up to about half its health per cycle."},{"n":"Descend","kind":"trav","goal":"Use a red circuit to open a ventilation shaft, then clear a room of yellow circuits and Arc gates.","steps":["The second hidden chest is in this section (see chests)."]},{"n":"Persys, Primordial Ruin","kind":"enc","goal":"Lure Persys into the reactor room, seal it in for the purge and damage it when it comes out without its shield.","steps":["Shoot or approach Persys to start. It comes out of the reactor core and the core closes.","Kill the two Incarcerator Hydras on opposite sides of the arena so Conduit Minotaurs spawn.","With Arctrician, activate the nodes on the pillars and above the main door to open the reactor room.","Complete two of the yellow reactor circuits. \"Reactor Purge Imminent, Seek Safety\" appears. Persys must be inside the reactor room before you finish.","Retreat to the safe room, refresh Arctrician and activate the red circuit (the inner pillar nodes and the top node) to seal the doors.","When the purge finishes, the doors open and Persys comes out vulnerable, with a small core weak point. Damage it.","If it survives, it recharges its shield and you repeat the purge."],"dps":"Short and tight; shoot the small core weak point.","wipes":["If Persys isn't in the reactor room during the purge, its shield stays up and you have to redo it."]}],"chests":["Begin the Ascent: jump across the objects hanging from the cranes to the second high catwalk. Go around the back of the pillars to the catwalk leading away from the central pillar, cross the small ledge between catwalks; the chest sits on a ledge behind the last pillar.","Descend (Arc gate room): check the vent covers under the stairs in each corner. One opens into a ventilation shaft with the chest."],"extra":{"t":"Hierarchy of Needs","b":["Hierarchy of Needs, an exotic Solar bow, is a random drop from the final boss chest."]},"lootAll":["Long Arm","Liminal Vigil","Terminus Horizon","Wilderflight","Seventh Seraph Carbine","Seventh Seraph Officer Revolver","TM Custom armor (Cogburn, Earp, Moss)","Hierarchy of Needs (exotic bow)"],"lootNote":"The in-app list loads Bungie's own collection data, so it stays correct if the pool changes.","src":[["Destinypedia: Spire of the Watcher","https://www.destinypedia.com/Spire_of_the_Watcher"],["Shacknews: Spire of the Watcher guide","https://shacknews.com/article/133423/spire-of-the-watcher-guide"]],"b":"Spire of the Watcher","k":["Spire of the Watcher"],"pl":{"1_0":3,"1_1":2,"2_0":0,"2_1":0,"2_2":0,"3_0":5,"3_1":5,"4_0":"rest"}},{"id":"sd","n":"Sundered Doctrine","type":"Dungeon","players":"3","loc":"The Sunken Pyramid, Court of Savathûn (Throne World)","rel":"Episode: Heresy (February 7, 2025)","intro":"A Hive and Dread dungeon inside Rhulk's pyramid. It's a puzzle dungeon: route light through lenses to symbol wheels, rotate the wheel with knowledge shards, and lock in the right symbols to open doors and boss shields.","basics":["Lenses: kill a Lens Bearer for a lens and place it on a pedestal to bend the light beam.","Truthspeakers reveal symbols. Wheels of symbols are the answer key for each puzzle.","Knowledge shards from Preceptors rotate a wheel's light: Heightened moves it 1 space, Brimming 2, Overflowing 3."],"enc":[{"n":"Find the Path","kind":"trav","goal":"Get behind the waterfall and through the tunnels to the rally flag.","steps":["Kill the Subjugators in the tunnels.","Some platforms lower when you stand on them and rise when you step off. Light beams hurt if you stand in them."]},{"n":"Solve the Riddle","kind":"enc","goal":"Route the pedestal's light beam to the wheel showing the right symbols.","steps":["Kill a Truthspeaker to learn the third symbol.","Kill a Lens Bearer for a lens and place it on a pedestal (the Lens Bearer respawns).","Shoot the Pyramid switch to send the beam to the correct wheel.","A wrong route breaks the outer lenses and spawns a Tormentor."]},{"n":"Navigate the Maze","kind":"trav","goal":"Rotate the wheel light with knowledge shards to match the door symbols.","steps":["Dodge the spiked boulders and jump through the holes.","Kill Preceptors for knowledge shards and use them to rotate the wheel light 1, 2 or 3 spaces until it matches the door.","The first hidden chest is in this maze (see chests)."]},{"n":"Zoetic Lockset (Open the Locks)","kind":"enc","goal":"Lock symbols on the wheels in a good order, ending with Kill to start damage.","steps":["Only one wheel can rotate at a time; the Lockout Progression buff shows which.","Each locked symbol does something: Hive spawns Ogres, Remember spawns Wizards, Commune makes the Lockset fire Resonant Sun projectiles, Stop stops enemy spawns.","Kill starts the damage phase. The more symbols you lock before Kill, the longer damage lasts.","Some parts of the boss close their shells during damage. Afterwards, bring the core to the bowl near the loot chest to move on."],"dps":"Lock as many safe symbols as you can before Kill to stretch the damage phase."},{"n":"Locate the Vault","kind":"trav","goal":"Follow the worm carcass path and line up light beams on the wheel symbols to open the barrier.","steps":["A wall slowly closes and crushes you if you stay near it too long.","The second hidden chest is here, up in a giant worm mouth in the wall (see chests)."]},{"n":"Kerrev, the Erased","kind":"enc","goal":"Break Kerrev's Strand tethers, light the right symbols on the dial and trigger the fire trap to drop its shield.","steps":["Kerrev summons Pyramid spikes held by Strand tethers.","Kill an Unwritten Attendant for Unwritten Empowerment (7 seconds). Only with it can you destroy the tethers. Damaging tethers releases Threadlings.","Pick the truth side or the lie side of the dial. Truthspeakers only drop truth symbols.","Light the chosen symbols, then use the pillar to set off the fire trap.","When Kerrev's shield drops, damage Kerrev. Repeat until it dies."]}],"chests":["Maze (after the first encounter): destroy the three Darkness Crux hidden in the maze. Back out of the narrow path, crouch and go straight; the chest is in a newly opened section on your left.","Locate the Vault (between the second and third encounters): look at the Worm symbol, then look up and to the right for a large Worm mouth in the wall. Climb up into it."],"extra":{"t":"Finality's Auger","b":["Finality's Auger, an exotic Solar linear fusion rifle, drops from the final boss."]},"lootAll":["Unloved","Unsworn","Unworthy","Unvoiced","Flain armor","Finality's Auger (exotic linear fusion)"],"lootNote":"The in-app list loads Bungie's own collection data, so it stays correct if the pool changes.","src":[["Destinypedia: Sundered Doctrine","https://www.destinypedia.com/Sundered_Doctrine"],["Sportskeeda: Sundered Doctrine secret chests","https://sportskeeda.com/mmo/destiny-2-sundered-doctrine-secret-chest-locations"]],"b":"Sundered Doctrine","k":["Sundered Doctrine"],"pl":{"0_2":"rest","1_0":5,"2_0":1,"2_1":1,"3_0":3,"3_1":5,"3_2":5}},{"id":"vh","n":"Vesper's Host","type":"Dungeon","players":"3","loc":"Vesper Station (Europa orbit)","rel":"Episode: Revenant (October 11, 2024)","intro":"A Fallen and Vex dungeon on a BrayTech station orbiting Europa. Two buffs run the show: the Viral Scanner sees which panel or number is correct, and the Viral Operator shoots it. Nuclear cores do the heavy lifting, but carrying them builds Radiation.","basics":["Viral Scanner: lets you see the correct panels, numbers or clones. Viral Operator: lets you shoot and activate them. Viral Carriers drop these buffs.","Nuclear cores: carry them to the marked bucket or bunker. Holding one adds Radiation stacks; at 10 you die, so swap carriers.","Integration: Raneiks Unified's beam on anyone it can see. Break line of sight or it kills you."],"enc":[{"n":"Activation","kind":"enc","goal":"Drop nuclear cores with the Scanner and Operator and deposit them in the main room, three times.","steps":["Kill the Viral Carriers to get the Scanner and Operator buffs.","The Scanner finds the right panel; the Operator shoots it so it drops a nuclear core.","Kill the Brig (and the Machine Priest's Assistant) to remove the shielding on the bucket, then carry the core to the main room and deposit it.","Swap core carriers before anyone reaches 10 Radiation stacks. Repeat two more times; the last Brig is a boss-type enemy."],"wipes":["10 Radiation stacks kills the carrier."]},{"n":"Integration & Nukes","kind":"enc","goal":"Work through the door maze with Power Reserves and deposit nuclear cores in the numbered buckets in order.","steps":["Fallen terminals give Power Reserves (up to 4). Opening a BrayTech door costs one; closing a door gives one back.","Raneiks Unified patrols the maze and beams anyone it can see (Integration). Use doors and corners to break line of sight.","Captains drop nuclear cores. Deposit them in the buckets numbered 1 to 5, in order. Each deposit spawns the next Captain."],"wipes":["Staying in Raneiks's line of sight while Integrated."]},{"n":"Raneiks Unified","kind":"enc","goal":"Find the four numbered Servitors, shoot the matching panels and damage Raneiks.","steps":["Kill the Machine Priest to trigger Servitor's Fall, which teleports you upstairs.","Shanks upstairs drop the Suppressor buff. Its grenade makes a decoy that splits Raneiks into Servitors.","Look for the numbered Servitors with extra face lights (Raneiks-1, Raneiks-2 and so on) and call out the number. Repeat until you have four.","The Operator shoots the four matching numbered pads (0–9) to start damage."],"dps":"25 seconds, starting when the Suppressor Shank appears. Raneiks splits again during damage, so area supers and weapons work well."},{"n":"Acceleration","kind":"trav","goal":"Make your way through the station while anomaly energy strikes it.","steps":["Arc strikes hit the station; keep moving and stay out of them."]},{"n":"The Corrupted Puppeteer","kind":"enc","goal":"Strip the clones' Radiation auras, find the real copy, deposit two cores in the bunkers and damage the Puppeteer.","steps":["The Broken Puppets give off a Radiation field. Use the Suppressor's decoy near them and kill the decoy to remove their field and immunity shield.","The Scanner finds the correct panel; the Operator shoots it and matches the blue number on the other panels.","In the lower area, the Operator activates panels and copies of the boss appear. The Scanner marks the one to destroy.","Deposit two nuclear cores in the bunkers to remove the boss's immunity shield. A slightly different Broken Puppet drops the core for the left bunker.","Damage comes in two rounds on the deck, with a bunker deposit between them. Watch for lightning strikes."],"wipes":["10 Radiation stacks kills you.","A Viral Augment kills the player holding it after 1 minute unless it's deposited in an Augment Terminal."]}],"extra":{"t":"Ice Breaker","b":["Ice Breaker, the exotic Solar sniper rifle, returns as this dungeon's exotic and drops from the final boss."]},"lootAll":["VS Chill Inhibitor","VS Gravitic Arrest","VS Pyroelectric Propellant","VS Velocity Baton","Spacewalk armor","Ice Breaker (exotic sniper)"],"lootNote":"The in-app list loads Bungie's own collection data, so it stays correct if the pool changes.","src":[["Destinypedia: Vesper's Host","https://www.destinypedia.com/Vesper%27s_Host"],["Shacknews: Vesper's Host guide","https://shacknews.com/article/141768/destiny-2-vespers-host-guide"]],"b":"Vesper’s Host","k":["Vesper's Host"],"pl":{"1_0":1,"1_1":1,"2_0":0,"2_1":0,"2_2":0,"2_3":2,"2_4":2,"2_5":2,"2_6":2,"2_7":4,"2_8":4,"2_9":4,"2_10":4,"2_11":4,"2_12":2,"2_13":4,"2_14":"rest","2_15":4}},{"id":"wr","n":"Warlord's Ruin","type":"Dungeon","players":"3","loc":"Windswept Crag, European Dead Zone (Earth)","rel":"Season of the Wish (December 1, 2023)","intro":"A Scorn dungeon in a snowbound castle in the EDZ. The core loop: during Imminent Wish, stand in the marked area to cleanse corrupted Ether Totems; when the Wish ends you get Naeem's Wish Empowerment, and the more totems you cleansed, the longer it lasts.","basics":["Imminent Wish: while it's active, standing in a marked area cleanses a corrupted Ether Totem.","Naeem's Wish Empowerment: the damage buff you get afterwards. Its length scales with how many totems you cleansed.","Blighted Eyes shield bosses and objectives. Shooting them starts each cycle."],"enc":[{"n":"Rathil, First Broken Knight of Fikrul","kind":"enc","goal":"Cleanse totems during Imminent Wish, escape Rathil's cages, then damage him with Naeem's Wish Empowerment.","steps":["During Imminent Wish, stand in the marked areas to cleanse the Ether Totems.","Rathil teleports players into cages up high. Kill the three Blighted Eyes around your cage to open the door, drop down and get back to cleansing.","When Imminent Wish ends, Rathil's hex backfires and gives you Naeem's Wish Empowerment. Damage him while it lasts."],"dps":"Your damage window is as long as Naeem's Wish Empowerment, so cleanse as many totems as you can."},{"n":"Imprisoned!","kind":"trav","goal":"Set all six cell nodes spinning the right way, then shoot the glowing lever.","steps":["Shooting a circular node once makes it spin counter-clockwise; twice makes it spin clockwise.","Tally marks on the skeletons in two cells tell you the direction for each node.","When all six are right, shoot the glowing lever on a cell lock. A wrong attempt resets every node."]},{"n":"Venture Deeper","kind":"trav","goal":"Climb the cliff path and cross into the castle bailey.","steps":["Wall spikes fire when you step in front of them. Jump the pits.","Loose rocks on the cliff can knock you off.","The Blighted Chimaera attacks on the castle bridge. A sewer drain on the mountainside leads to the bailey.","The first hidden chest is between Rathil and Locus of Wailing Grief."]},{"n":"Locus of Wailing Grief","kind":"enc","goal":"Cleanse totems, survive the snowstorm, light the four central pillars with Solar Charges and damage the Locus.","steps":["Shoot the Blighted Eyes to start Imminent Wish. Broken Knights spawn on each side; cleanse their totems.","Cleansing brings a snowstorm that adds Biting Cold. Stand near a torch for Shelter From The Storm, which clears all your stacks within 5 seconds.","Solar Charges spawn at the back of the arena. Deposit them in the four central pillars. How many charges you get depends on how many totems you cleansed.","If the pillars aren't all lit, the Blighted Eyes come back and you repeat.","After the fourth pillar is lit, damage starts. Stand near a pillar for Shelter and Naeem's Wish Empowerment. A used pillar needs another Solar Charge before it works again."],"wipes":["10 stacks of Biting Cold freezes and kills you."]},{"n":"Hefnd's Vengeance, Blighted Chimaera","kind":"enc","goal":"Cleanse totems, pass the Hex of Vengeful Corruption to Hex-Drinkers, and push the Chimaera down floor by floor.","steps":["Shoot the Blighted Eyes shielding the Chimaera. Two Broken Knights spawn on each side; cleanse their totems during Imminent Wish.","Hex of Vengeful Corruption lasts 15 seconds. Get rid of it by meleeing a Corrupted Hex-Drinker, which can hit you back and give it to you again.","Damage with Naeem's Wish Empowerment. If you don't deal enough, the Chimaera stays on the same floor and you repeat.","On the last floor, three platforms give Naeem's Wish Empowerment while you stand on them; shooting Blighted Eyes extends it. When it runs out, the Chimaera teleports to another platform.","The final stand gives Naeem's Wish Empowerment with no time limit. Finish it."],"wipes":["Holding the Hex of Vengeful Corruption when it expires kills you."]}],"chests":["One hidden chest between Rathil and Locus of Wailing Grief, and one between Locus and Hefnd's Vengeance.","Each run, two of several chest spots are the real hidden chests and the others are traps."],"extra":{"t":"Buried Bloodline","b":["Buried Bloodline, an exotic Void sidearm, is a rare drop from Hefnd's Vengeance.","Its catalyst is tied to a hidden fight against Primeval Thressia, Font of Blight."]},"lootAll":["Dragoncult Sickle","Naeem's Lance","Indebted Kindness","Vengeful Whisper","Dark Age armor","Buried Bloodline (exotic sidearm)"],"lootNote":"The in-app list loads Bungie's own collection data, so it stays correct if the pool changes.","src":[["Destinypedia: Warlord's Ruin","https://www.destinypedia.com/Warlord%27s_Ruin"],["Kyber's Corner: Warlord's Ruin","https://kyberscorner.com/destiny2/warlords-ruin-dungeon/"]],"b":"Warlord’s Ruin","k":["Warlord's Ruin"],"pl":{"1_0":0,"2_0":3,"3_0":1,"4_0":4,"5_0":1,"5_1":1,"5_2":0,"5_3":0,"5_4":4,"5_5":0,"5_6":4,"5_7":3,"5_8":3,"5_9":3}},{"id":"encore","n":"Encore","type":"Exotic mission","players":"3","loc":"Deep inside Nessus","rel":"Episode: Echoes, Act III (August 2024)","intro":"A Vex puzzle mission inside Nessus built around three carryable modules: Connection builds bridges and lowers barriers, Partition removes wall chunks, and Access powers Vex teleporters. Reward: Choir of One.","basics":["Connection: place it in a dish to build segments and lower barriers.","Partition: removes chunks of wall.","Access: powers Vex teleporters."],"enc":[{"n":"Ascent","kind":"trav","goal":"Climb the wall on the right, drop through the sphere, ride the brick elevators and the piston, and drop through the purple hole."},{"n":"Connection and Partition","kind":"enc","goal":"Use Connection to power three pillars and open the door, then escape the electric wall.","steps":["Place Connection in the dishes to activate three pillars, then return it to the first dish to open the door.","Carry the second Connection down the hallway while a large electric wall chases you, and deposit it at the exit.","Clear the Vex to get a Partition."]},{"n":"Access","kind":"enc","goal":"Use Access nodes to power the teleporters and reach the rally banner."},{"n":"Subjugator","kind":"enc","goal":"Chase it through portals, kill the Tormentors for Access codes, and take a third of its health so it disappears."},{"n":"Research lab","kind":"trav","goal":"Climb through the cavern, then use the Proximity Sensor to find the Exo body. The wall to the central room opens."},{"n":"Parodos, Choral Mind","kind":"enc","goal":"Build the bridge, capture the plate, destroy the weak point and damage Parodos.","steps":["Each time you return to the centre, deposit Connection in the centre dish and use the pillar.","Later, barriers block jumping; use portals powered by Access nodes from the large Minotaurs.","Final phase: destroy the diamond to drop the shield.","If the weak-point diamond never spawns, the mission is stuck: wipe and reset."]}],"lootAll":["Choir of One (exotic auto rifle)"],"src":[["Shacknews: Encore exotic mission guide","https://shacknews.com/article/141186/encore-exotic-mission-destiny-2"]],"lootNote":"The in-app list loads Bungie's own collection data where available.","b":"","k":["Encore"]},{"id":"kell","n":"Kell's Fall","type":"Exotic mission","players":"3","loc":"The Revenant Fortress, Tangled Shore","rel":"Episode: Revenant, Act III (2025)","intro":"A Scorn fortress run that keeps flipping you between the material world and the Revenant Plane. Three variants (Reflection, Distortion, Diffraction) change the final boss.","basics":["Shoot the cracks in archways to switch between the material plane and the Revenant Plane."],"enc":[{"n":"Gatehouse","kind":"enc","goal":"Fight Araskes, the Trickster until she flees at about 3/5 health, then light the braziers to open the Mirror Gallery."},{"n":"Fighting Pit","kind":"enc","goal":"In the Revenant Plane, collect 10 Revenant Essence for Revenant Empowerment and kill the Pit Enforcers.","steps":["Kill the Pit Boss and Revenant Essentia, build 10 stacks of Revenant Essence, then use Revenant Empowerment on the Pit Enforcers.","Kill Kaniks, the Mad Bomber."]},{"n":"Undercroft","kind":"trav","goal":"Platforms and tunnels. A shrine door here takes an organ key sequence (see secrets)."},{"n":"Battle on Two Planes","kind":"enc","goal":"Keep re-entering the Revenant Plane while you kill Hiraks, the Mindbender and Araskes.","steps":["Refracting lasts 2:10. Go back into the Revenant Plane before it ends or you get Shattering."]},{"n":"Throne Room","kind":"enc","goal":"Fight Fikrul, the Fanatic and the variant's final boss.","steps":["Get into the Revenant Plane before Fikrul's wipe attack finishes.","The final boss is Reksis Vahn (Reflection), the Screeb Matriarch (Distortion) or Fikrul himself (Diffraction). On Diffraction, stun him by shooting an archway during his wipe attack."]}],"extra":{"t":"Secrets","b":["Uldren's shrine: play organ keys 1-8-4-11-1-6-4-10 to open the door.","Scorned Organist (Diffraction only): play 10-4-6-1-11-4-8-1. Killing the secret Tormentor lowers its immunity shield."]},"lootAll":["Slayer's Fang (exotic Void shotgun)","Catalysts via Eido's Revenant Slayer quests"],"src":[["Destinypedia: Kell's Fall","https://destinypedia.com/Kell%27s_Fall"]],"lootNote":"The in-app list loads Bungie's own collection data where available.","b":"","k":["Kell's Fall"]},{"id":"avalon","n":"//NODE.OVRD.AVALON//","type":"Exotic mission","players":"3","loc":"The Gulch, European Dead Zone (Earth)","rel":"Lightfall (2023)","intro":"A Vex simulation built by a friendly Harpy: shape puzzles, data motes, platforming and a final boss chase. You walk out with the Vexcalibur glaive.","basics":["Start: find the six Vex cubes in the Gulch for the passcode, then talk to the Friendly Harpy in the cave that opens at the top right.","Each player has 2 revives, and a downed player must be picked up within 30 seconds."],"enc":[{"n":"Radiolaria Corridors","kind":"trav","goal":"Drop down the chute, use doors and platforms to reach the green light and activate the node, then take the elevator down."},{"n":"Security Protocol","kind":"enc","goal":"Clear the gates by destroying shapes in the right order.","steps":["Codes are 3, then 4, then 5 symbols. The pyramid can't be destroyed. A wrong shape changes the sequence.","Clear both confluxes, then kill the Digital Variant Tracker and the Digital Variant Neutralizer."]},{"n":"Suspended Platforms","kind":"trav","goal":"Cross the disappearing steps and crawlspaces to the rally banner and take the man cannon."},{"n":"Data Nullifier","kind":"enc","goal":"Deposit data motes in the central spire to bring out and kill the Data Nullifier.","steps":["Kill Dataholders for motes and deposit 8, then 10. The pit protects you from the wipe timer, but Wyverns can still hit you there.","After half its health is gone, deposit 10, then 12 more for the second damage phase."]},{"n":"Separated Constructions","kind":"trav","goal":"Long jumps and man cannons to the portal, elevator and rally banner."},{"n":"Brakion, Repurposed Mind","kind":"enc","goal":"Chase Brakion through three arenas.","steps":["Phase 1: it teleports between corners and fires Void flames. Damage it until it leaves, then take the portal.","Phase 2: kill the Encryption Daemon, then solve three shape combinations at the central spire to open damage. Repeat until it teleports away.","Final arena: headless and enraged, it sprints at people. Use the cover blocks to slow it down.","Afterwards, Vexcalibur appears in front of the highest Radiolaria waterfall. Take it to finish."]}],"lootAll":["Vexcalibur (exotic glaive)","Vexcalibur catalyst (Master, one per week)"],"src":[["Destinypedia: NODE.OVRD.AVALON walkthrough","https://www.destinypedia.com/NODE.OVRD.AVALON/Walkthrough"]],"lootNote":"The in-app list loads Bungie's own collection data where available.","b":"","k":["NODE OVRD AVALON"]},{"id":"seraph","n":"Operation: Seraph's Shield","type":"Exotic mission","players":"3","loc":"Seraph Station (Earth orbit)","rel":"Season of the Seraph (2022/23); returned in Season of the Witch","intro":"Infiltrate a Warsat station and plant a virus in the network, fighting through House Salvation, the Hive and finally Scorn.","enc":[{"n":"Launch facility","kind":"trav","goal":"Clear the Hive and Fallen, take the security protocol from a House Salvation splicer and prime the pods to reach the station."},{"n":"Station","kind":"trav","goal":"Decompile the scanner protocol at the door terminal and cross the station using augments.","steps":["At the dead end, surrender to be captured; it's part of the plan."]},{"n":"Haroktha, Scourge of the Helium Drinkers","kind":"enc","goal":"Defeat the Hive boss along the way."},{"n":"Praksis the Defiled","kind":"enc","goal":"Fight through to the final room and kill Praksis and the Scorn."}],"lootAll":["Revision Zero (exotic pulse rifle)","Revision Zero catalyst (Master)"],"src":[["Destinypedia: Operation: Seraph's Shield","https://www.destinypedia.com/Operation:_Seraph%27s_Shield"]],"lootNote":"The in-app list loads Bungie's own collection data where available.","b":"","k":["Seraph's Shield"]},{"id":"presage","n":"Presage","type":"Exotic mission","players":"3","loc":"The Glykon Volatus (derelict Cabal carrier)","rel":"Season of the Chosen (2021); returned in Season of the Witch","intro":"A horror-tinged trip through a ghost ship overrun by Scorn, looking for what happened to its captain. Mostly traversal and Scorn fights, with lots of hidden lore.","basics":["Master (the hard version) has a 25-minute limit and Contest rules, so enemies are above your level."],"enc":[{"n":"Boarding","kind":"trav","goal":"Get inside through the hull vent and the vents beyond.","steps":["Shoot the spores blocking the entrance door, then pass the spore room and the small hatch tunnel.","Get past the electric fields, fighting Scorn and spores."]},{"n":"Trash compactor","kind":"trav","goal":"Disable the active compactor and drop through the hatch in its floor."},{"n":"Locked room and hangar","kind":"enc","goal":"Survive the Darkmind Abomination and clear the hangar.","steps":["A large Scorn tries to break into the locked room, then teleports away and sends minions.","Clear the big Scorn horde in the hangar and keep disabling electric fields."]},{"n":"Locus of Communion","kind":"enc","goal":"Kill the final boss in the boiler room, then drop through the vent to the bridge and examine Captain Katabasis's body."}],"extra":{"t":"Secrets","b":["12 smuggling compartments each hold a small chest and advance the Dead Man's Tale catalyst. They unlock as you collect Captain's Log lore; use the datapad nearby.","15 Glykon clues unlock in weekly sets; finding all of them gives the Shell of Gilgamesh ghost."]},"lootAll":["Dead Man's Tale (exotic scout rifle)","Dead Man's Tale catalyst (Master)"],"src":[["Destinypedia: Presage","https://www.destinypedia.com/Presage"]],"lootNote":"The in-app list loads Bungie's own collection data where available.","b":"Presage","k":["Presage"]},{"id":"starx","n":"Starcrossed","type":"Exotic mission","players":"3","loc":"Overland and the Black Garden","rel":"Season of the Wish (2024)","intro":"A run into the Black Garden to stop a Vex Mind, powered by paracausal sparks. Reward: the Wish-Keeper bow.","enc":[{"n":"Black Garden","kind":"trav","goal":"Cross the Garden and use paracausal sparks to open the structure."},{"n":"Obdurate Phalanx lock","kind":"enc","goal":"Use sparks to reveal three symbols, then kill the Phalanxes in that order.","steps":["A wrong order resets the lock."]},{"n":"Ixion, Covetous Mind","kind":"enc","goal":"Kill Ixion and its Vex to open the transit mechanism, then ride the Vex transit to the top."},{"n":"Gatekeeper Wyverns","kind":"enc","goal":"Kill three Gatekeeper Wyverns to weaken the barrier, then clear the area."},{"n":"Akardon, Pitiless Mind","kind":"enc","goal":"Combine paracausal energies to break Akardon's Ahamkara protection, then kill everything while the Mind is open."}],"lootAll":["Wish-Keeper (exotic Strand bow)"],"src":[["Destinypedia: Starcrossed","https://www.destinypedia.com/Starcrossed"]],"lootNote":"The in-app list loads Bungie's own collection data where available.","b":"","k":["Starcrossed"]},{"id":"vox","n":"Vox Obscura","type":"Exotic mission","players":"3","loc":"Meridian Bay (Mars)","rel":"Season of the Risen (2022); returned in Season of the Witch","intro":"A loud vehicle-heavy assault on a Psion broadcast site on Mars, run for Empress Caiatl. You steal an Interceptor, drive a tank and storm a bunker.","enc":[{"n":"Sneak into the Hangar","kind":"trav","goal":"Make your way through the base and steal an Interceptor."},{"n":"Vehicular Assault","kind":"enc","goal":"Clear the airfield, destroy the Goliath Tanks and take a Drake Tank to the broadcast site."},{"n":"Signal Towers","kind":"enc","goal":"Destroy the two Red Legion Goliaths in the Scablands and all three signal towers, then blast open the bunker door."},{"n":"Race to the Control Room","kind":"enc","goal":"Kill the Psion Codewardens and defeat Qabix, Insurgent, at the source of the broadcasts.","steps":["Open the golden Leviathan chest at the end."]}],"lootAll":["Dead Messenger (exotic grenade launcher)","Dead Messenger catalyst (Master)","Ivory Empress (exotic Sparrow, chance per run)"],"src":[["Destinypedia: Vox Obscura","https://www.destinypedia.com/Vox_Obscura"]],"lootNote":"The in-app list loads Bungie's own collection data where available.","b":"Vox Obscura","k":["Vox Obscura"]},{"id":"whisper","n":"The Whisper","type":"Exotic mission","players":"3","loc":"Io (portal near the Grove of Ulan-Tan)","rel":"Warmind (2018); reprised in 2024","intro":"A Taken jumping gauntlet on Io that ends with three old Taken bosses and, in the reprise, a giant Taken Ogre. The reward is Whisper of the Worm.","basics":["Normal has a 40-minute timer; Heroic (formerly Legend) has 20 minutes with Shielded Foes, plus Overload Hobgoblins and Unstoppable Phalanxes.","Taken traps and moving objects can knock you off platforms."],"enc":[{"n":"Jumping rooms","kind":"trav","goal":"Work through the jumping sections and clear each room of Taken Blights.","steps":["Kill everything in the first two rooms to clear their blights.","In the third room, break the blight over the large pit and drop down. A chest is waiting."]},{"n":"Vex prisons","kind":"enc","goal":"Free and kill Ta'aurc, Drevis and Urzok.","steps":["The three are locked in Vex prisons linked to Confluxes. Kill the adds, then break the Confluxes, in any order, and kill each boss."]},{"n":"Tulgorh, Aspect of Agony","kind":"enc","goal":"Break Tulgorh's shield by killing the Shield Weavers, then damage it.","steps":["Taken Shield Weavers keep Tulgorh shielded. Kill them to make it damageable.","It summons Shadow Thrall as it loses health.","At 40% it brings the Shield Weavers back along with several blights. Repeat and finish it."]}],"extra":{"t":"Heroic secrets","b":["With Eris Morn's quest, small floating blights appear that only Whisper of the Worm can destroy. Destroying a group and finishing awards a catalyst.","Seven hidden Oracles: destroy all of them for both parts of Whisper's enhanced intrinsic and the Karve of the Worm ship."]},"lootAll":["Whisper of the Worm (exotic sniper)","Whisper of the Worm catalysts (Heroic)"],"src":[["Destinypedia: The Whisper","https://www.destinypedia.com/The_Whisper"]],"lootNote":"The in-app list loads Bungie's own collection data where available.","b":"Whisper of the Worm","k":["The Whisper"]},{"id":"zh","n":"Zero Hour","type":"Exotic mission","players":"3","loc":"The Old Tower (the Last City)","rel":"Season of the Drifter (2019); reprised in 2024","intro":"A timed run through the ruins of the Old Tower to stop Siriks and House Salvation. Fast clears and a vent maze, then a boss that comes back in a giant Brig.","basics":["Normal has a 40-minute timer; Heroic (formerly Legend) has 20 minutes with Shielded Foes.","Every combat room has to be cleared before the next door opens."],"enc":[{"n":"Old Tower","kind":"trav","goal":"Clear the courtyard and combat rooms. A Brig joins the Shanks in the courtyard."},{"n":"Vents and jumping","kind":"trav","goal":"Get through the ventilation maze and jumping puzzles.","steps":["Switches along the way make the route easier for teammates behind you."]},{"n":"The sweeper maze","kind":"trav","goal":"Hit all four switches in the big maze while avoiding TR3-VR, the malfunctioning sweeper bot.","steps":["Go through the door at the back of the maze to the room with four elevators. They drop before you reach the top, so keep moving."]},{"n":"Siriks, of House Salvation","kind":"enc","goal":"Push Siriks to about 40%, destroy the two Walkers, then kill the giant Brig he returns in.","steps":["Siriks retreats at roughly 40% health.","Destroy the two Walkers. Siriks comes back piloting a giant Brig with Mimiks-2 and reinforcements.","Destroy the Brig to finish."]}],"extra":{"t":"Heroic puzzles","b":["Heroic needs Banshee-44's quest for its switch and vault puzzles.","Switch puzzle: pulling a switch starts a timer; find its pair before it ends. Completing it awards Outbreak Perfected catalysts.","Vault puzzle: shoot the correct SIVA symbols on the panels to open a barrier. It awards enhanced intrinsics and the Vimana Junker ship."]},"lootAll":["Outbreak Perfected (exotic pulse rifle)","Outbreak Perfected catalysts (Heroic)"],"src":[["Destinypedia: Zero Hour","https://www.destinypedia.com/Zero_Hour"]],"lootNote":"The in-app list loads Bungie's own collection data where available.","b":"Zero Hour","k":["Zero Hour"]}];
